insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('gift-budget-per-person-envelope-sheet', 'Gift Budget Per Person Envelope Sheet', 'worksheet'::resource_kind, 'A planning sheet that sets a spending cap per person before the season''s shopping starts, with a line for what the gift is meant to say.', 'Use it to swap gift guilt and last-minute overspending for a number decided ahead of time.', array['Adults']::text[], '20 minutes before the first shopping trip', 'Spending stress in December is usually decided in the store, not at the kitchen table. The sheet asks for the total the client can spend without dread, then a name-by-name split, then one line per person on what the gift is meant to say, which often shrinks the number. The last box is the client''s rule for the moment a tempting thing costs more than the envelope. Watch for the client who budgets for everyone but themselves, and for the one whose envelopes add up to twice the total; both are worth a conversation in session.', '[{"id": "f0", "type": "textarea", "label": "The total I can spend this season without dreading January:"}, {"id": "f1", "type": "textarea", "label": "Each person I am buying for, and their envelope amount:"}, {"id": "f2", "type": "textarea", "label": "For each person, what the gift is meant to say (one line each):"}, {"id": "f3", "type": "textarea", "label": "What I will do when something costs more than the envelope:"}, {"id": "f4", "type": "textarea", "label": "One gift that could be time or a favor instead of money:"}, {"id": "f5", "type": "textarea", "label": "How I will keep the running total (app, note, receipts in the envelope):"}]'::jsonb, array['money', 'planning', 'holidays']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('returning-to-work-after-four-days-off-re-entry-sheet', 'Returning to Work After Four Days Off Re-Entry Sheet', 'worksheet'::resource_kind, 'A sheet for the night before going back to work after a long weekend, sorting the first morning into what waits and what cannot.', 'Use it to land the first day back on a short list instead of the whole inbox.', array['Adults']::text[], '15 minutes the night before', 'The dread the night before a return to work is mostly about the imagined pile. The sheet asks the client to guess what is waiting, then to name the two things that truly cannot wait past noon and the things that can sit a day, then to plan the first hour so it begins with something small and finished. A box for what they will say to the first coworker who asks about the break keeps the social part from being another worry. Watch for the client who plans to arrive early and stay late to catch up in one day; that is the plan to question.', '[{"id": "f0", "type": "textarea", "label": "What I imagine is waiting for me:"}, {"id": "f1", "type": "textarea", "label": "The two things that truly cannot wait past noon tomorrow:"}, {"id": "f2", "type": "textarea", "label": "What can sit for a day or more without harm:"}, {"id": "f3", "type": "textarea", "label": "My first hour, starting with one small thing I can finish:"}, {"id": "f4", "type": "textarea", "label": "What I will say when someone asks how the break was:"}, {"id": "f5", "type": "textarea", "label": "When I will stop tomorrow, and what I will leave for Tuesday:"}]'::jsonb, array['work', 'planning', 'stress']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('hand-me-down-furniture-keep-or-pass-on-decision-sheet', 'Hand-Me-Down Furniture Keep or Pass On Decision Sheet', 'worksheet'::resource_kind, 'A decision sheet for the inherited or gifted furniture that fills a room but carries a relative''s feelings.', 'Use it to separate what a piece of furniture means from where it has to live.', array['Adults']::text[], '30 minutes', 'Furniture from a relative is hard to move along because the client hears the giver''s voice in the decision. The sheet asks what the piece is, who it came from, what the client fears the giver would say, what the piece costs them in space or use, and what they would keep if they could keep only its meaning (a photo, a drawer pull, the story). The last box is the decision and one sentence for the giver if they ever ask. Watch for the client whose home is arranged around other people''s choices; this sheet often opens that larger conversation.', '[{"id": "f0", "type": "textarea", "label": "The piece, who it came from, and how it arrived in my home:"}, {"id": "f1", "type": "textarea", "label": "What I imagine the giver would say if I passed it on:"}, {"id": "f2", "type": "textarea", "label": "What it costs me to keep it (space, use, how the room feels):"}, {"id": "f3", "type": "textarea", "label": "What I would keep if I could keep only its meaning:"}, {"id": "f4", "type": "textarea", "label": "My decision, and the first step toward it:"}, {"id": "f5", "type": "textarea", "label": "One sentence I could say to the giver if they ask:"}]'::jsonb, array['decisions', 'family', 'boundaries']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('phone-battery-dying-away-from-home-steps-sheet', 'Phone Battery Dying Away From Home Steps Sheet', 'worksheet'::resource_kind, 'A problem-solving sheet for the moment the phone is about to die far from home, planned while it is still charged.', 'Use it to give the client a plan that does not live inside the device that is failing.', array['Adults', 'Teens']::text[], '15 minutes', 'A dying phone away from home is a small event that can feel like being cut off from everything. The sheet asks the client to write, on paper, the two numbers they would need, the address they are going to and how to get there without the map, where they tend to find an outlet or a charger, and what they will tell themselves while the screen is dark. Have the client fold the finished sheet into a wallet or bag. Watch for the client whose plan is to never let the battery drop below half; the sheet is about the time that plan fails.', '[{"id": "f0", "type": "textarea", "label": "The two phone numbers I would need, written here from memory or my contacts:"}, {"id": "f1", "type": "textarea", "label": "Where I am most often when the battery runs low, and the nearest place to charge:"}, {"id": "f2", "type": "textarea", "label": "How I get home from there without the map:"}, {"id": "f3", "type": "textarea", "label": "What I will say to whoever is waiting for me, before the screen goes dark:"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself while the phone is off:"}, {"id": "f5", "type": "textarea", "label": "What goes in my bag this week so this plan is easier:"}]'::jsonb, array['problem solving', 'planning', 'stress']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('saying-no-to-the-volunteer-committee-script-sheet', 'Saying No to the Volunteer Committee Script Sheet', 'worksheet'::resource_kind, 'A script sheet for declining a committee, board or volunteer role the client is being asked to take on again.', 'Use it to let the client decline a worthy ask without a reason that can be argued with.', array['Adults']::text[], '20 minutes', 'The hardest no is to a good cause asked for by a nice person. The sheet asks what the role is, who is asking, what the client expects to feel in the moment, and the sentence they will say, then has them strip it of any reason the asker could solve for them. A box for the second ask (the one that comes after the first no) is where the practice matters. Rehearse it aloud in session with you playing the persistent chair. Watch for the client who offers a smaller task instead of a no; sometimes that is a choice and sometimes it is the old pattern in a new coat.', '[{"id": "f0", "type": "textarea", "label": "The role I am being asked to take, and who is asking:"}, {"id": "f1", "type": "textarea", "label": "What I expect to feel when I say no to them:"}, {"id": "f2", "type": "textarea", "label": "My sentence, with no reason they can solve for me:"}, {"id": "f3", "type": "textarea", "label": "What I will say to the second ask:"}, {"id": "f4", "type": "textarea", "label": "What I will do with the time I am protecting:"}, {"id": "f5", "type": "textarea", "label": "How I will feel about this a week after saying it:"}]'::jsonb, array['assertiveness', 'boundaries', 'saying no']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('downward-arrow-on-being-picked-last-for-the-team-sheet', 'Downward Arrow on Being Picked Last for the Team Sheet', 'cbt'::resource_kind, 'A downward arrow sheet that starts with a small sting, being chosen last for a work or social team, and follows it to the belief underneath.', 'Use it to reach the core belief under a small social sting in one sitting.', array['Adults', 'Teens']::text[], '30 minutes in session', 'Being picked last in a meeting or a pickup game is a small event with a long tail. The sheet runs the classic downward arrow: the situation, the first thought, and then the same question five times (if that were true, what would it mean about me?). The client stops when the answer repeats or lands in a sentence about who they are. The last boxes ask how old that sentence feels and what the client would say to a friend who believed it. Run it in session; the bottom of the arrow is not a place to leave someone alone with homework.', '[{"id": "f0", "type": "textarea", "label": "The moment I was picked last, in a sentence:"}, {"id": "f1", "type": "textarea", "label": "My first thought when it happened:"}, {"id": "f2", "type": "textarea", "label": "If that were true, what would it mean about me?"}, {"id": "f3", "type": "textarea", "label": "And if that were true, what would it mean?"}, {"id": "f4", "type": "textarea", "label": "And if that were true? Keep going until the answer repeats:"}, {"id": "f5", "type": "textarea", "label": "How old does the sentence at the bottom feel, and when did I first hear it?"}, {"id": "f6", "type": "textarea", "label": "What I would say to a friend who believed that sentence about themselves:"}]'::jsonb, array['downward arrow', 'core beliefs', 'core CBT']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('walking-without-headphones-behavioral-experiment-sheet', 'Walking Without Headphones Behavioral Experiment Sheet', 'cbt'::resource_kind, 'A behavioral experiment that tests what the client predicts will happen on a walk with no music, podcast or call in their ears.', 'Use it to test the prediction that an unfilled mind is unbearable.', array['Adults', 'Teens']::text[], 'One walk, then 15 minutes', 'Many clients have not walked anywhere in years without something in their ears, and predict boredom, dread or a flood of thoughts if they try. The sheet records the prediction and how strongly it is believed, the walk itself (length, route), what happened minute by minute, and what the client makes of it. Keep the first walk short, ten minutes is plenty. Watch for the client who rates the experiment a failure because thoughts came; the question was whether they were unbearable, not whether they appeared.', '[{"id": "f0", "type": "textarea", "label": "What I predict will happen if I walk ten minutes with nothing in my ears:"}, {"id": "f1", "type": "textarea", "label": "How strongly I believe that (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "The walk: where, how long, what time of day:"}, {"id": "f3", "type": "textarea", "label": "What happened, in order, including the thoughts that came:"}, {"id": "f4", "type": "textarea", "label": "How bad it got at its worst (0 to 100), and how long that lasted:"}, {"id": "f5", "type": "textarea", "label": "What this tells me about my prediction, and what I will try next:"}]'::jsonb, array['behavioral experiment', 'predictions', 'core CBT']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('mental-filter-over-the-one-burned-cookie-sheet', 'Mental Filter Over the One Burned Cookie Sheet', 'cbt'::resource_kind, 'A mental filter sheet for the client who remembers the one burned cookie from a tray of two dozen and nothing else about the evening.', 'Use it to catch the filter that keeps one flaw and drops everything else.', array['Adults', 'Teens']::text[], '15 minutes', 'The mental filter is easiest to see in a small, concrete scene, and baking gives a perfect one: two dozen cookies, one burned, and the whole evening remembered as the burned one. The sheet asks for the scene, the one detail the mind kept, a full inventory of what else happened, what percentage of the evening the kept detail actually was, and what the evening looks like with the filter off. Have the client find their own burned cookie from the last week. Watch for the client who argues the one flaw was the one that mattered; ask who else noticed.', '[{"id": "f0", "type": "textarea", "label": "The scene, and the one detail my mind kept:"}, {"id": "f1", "type": "textarea", "label": "Everything else that happened, listed without skipping the ordinary parts:"}, {"id": "f2", "type": "textarea", "label": "How much of the evening the kept detail actually was:"}, {"id": "f3", "type": "textarea", "label": "Who else noticed the detail, as far as I can tell:"}, {"id": "f4", "type": "textarea", "label": "The evening described with the filter off:"}, {"id": "f5", "type": "textarea", "label": "Where else this week my mind kept the burned cookie:"}]'::jsonb, array['mental filter', 'thinking traps', 'core CBT']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('fortune-telling-the-dentist-appointment-sheet', 'Fortune Telling the Dentist Appointment Sheet', 'cbt'::resource_kind, 'A fortune telling sheet for the week of predictions that run ahead of a dental appointment, checked against what the visit was like.', 'Use it to put a dreaded appointment''s predictions on paper and compare them with the day.', array['Adults', 'Teens']::text[], '10 minutes before and after', 'A dental visit is a reliable place to catch fortune telling because the appointment is scheduled and the predictions are specific: it will hurt, they will find something, the hygienist will lecture. The sheet lists each prediction with a confidence rating before the visit, and after it, what actually happened and how the client''s body felt in the chair. The point is not that nothing bad happens at the dentist; it is the gap between the forecast and the day. Watch for the client who postpones the appointment rather than fill the sheet; that is the avoidance to name.', '[{"id": "f0", "type": "textarea", "label": "The appointment, and when it is:"}, {"id": "f1", "type": "textarea", "label": "My predictions about it, each with how sure I am (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "What I imagine I will feel in the chair:"}, {"id": "f3", "type": "textarea", "label": "After the visit: what actually happened, prediction by prediction:"}, {"id": "f4", "type": "textarea", "label": "What my body actually did in the chair:"}, {"id": "f5", "type": "textarea", "label": "What this tells me about my forecasts, and the next appointment I will test:"}]'::jsonb, array['fortune telling', 'thinking traps', 'health']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('graded-task-ladder-for-the-garage-cleanout-sheet', 'Graded Task Ladder for the Garage Cleanout Sheet', 'cbt'::resource_kind, 'A graded task assignment that breaks a garage or storage cleanout into steps small enough to start on a gray afternoon.', 'Use it to turn a task the client has avoided for a season into a first step they can take this week.', array['Adults']::text[], '20 minutes to plan, then one step a day', 'The garage cleanout is a classic avoided task: too big to start, too present to forget. Graded task assignment asks the client to name the finished picture, then build the ladder from the easiest rung (open the door and stand there for five minutes) to the hardest (the boxes from the old apartment), rating each for how hard it looks. They commit to the lowest rung only and log what happened. Watch for the client who skips to the top rung on a burst of motivation and quits; the ladder is the point, not the speed.', '[{"id": "f0", "type": "textarea", "label": "What the garage looks like when I am done, in a sentence:"}, {"id": "f1", "type": "textarea", "label": "The easiest possible first step, something I could do in five minutes:"}, {"id": "f2", "type": "textarea", "label": "The rest of the rungs, from easiest to hardest, each rated 0 to 10 for how hard it looks:"}, {"id": "f3", "type": "textarea", "label": "The rung I will do this week, and when:"}, {"id": "f4", "type": "textarea", "label": "What happened when I did it, and how hard it actually was:"}, {"id": "f5", "type": "textarea", "label": "Which rung is next:"}]'::jsonb, array['graded task', 'avoidance', 'behavioral activation']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('thoughts-as-coupons-i-do-not-have-to-clip-page', 'Thoughts as Coupons I Do Not Have to Clip Page', 'act'::resource_kind, 'A defusion page that treats the mind''s suggestions as a sheet of coupons: printed, insistent and optional.', 'Use it to give the client a light way to notice a thought''s offer without redeeming it.', array['Adults', 'Teens']::text[], '15 minutes, then daily practice', 'Coupons arrive whether or not you want them, each one shouting a deal, and most people let them expire without a second thought. The page asks the client to write the week''s loudest thoughts as coupons (the offer, the fine print, the expiration), then to notice which ones they clip automatically and what redeeming them costs. The practice is to read the coupon and leave it on the counter. This is defusion, not disputing: the coupon can be perfectly printed and still not worth clipping. Watch for the client who wants to prove the coupon is fake; that is a different exercise.', '[{"id": "f0", "type": "textarea", "label": "The three loudest thoughts this week, written as coupon offers:"}, {"id": "f1", "type": "textarea", "label": "The fine print on each (what I have to do or feel to redeem it):"}, {"id": "f2", "type": "textarea", "label": "Which ones I clip without thinking, and what redeeming them has cost me:"}, {"id": "f3", "type": "textarea", "label": "A coupon I will read this week and leave on the counter:"}, {"id": "f4", "type": "textarea", "label": "What I noticed when I let one expire:"}]'::jsonb, array['defusion', 'metaphor', 'core ACT']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('values-while-waiting-at-the-dmv-page', 'Values While Waiting at the DMV Page', 'act'::resource_kind, 'A values page for the long, dull wait at the DMV or any government counter, where the mind has nothing to do but complain.', 'Use it to show the client that values are available in the dullest hour of the week.', array['Adults', 'Teens']::text[], 'One wait, then 10 minutes', 'A long bureaucratic wait is a small laboratory: nothing to do, a mind full of judgment, and other people in the same chairs. The page asks the client to notice what their mind does in the wait, then to ask what kind of person they want to be in the room (patient, kind to the clerk, present to the stranger beside them) and to pick one small action that fits. The debrief asks what the wait was like with a chosen direction versus without one. Watch for the client who turns it into a performance of patience; the value is theirs, not the room''s.', '[{"id": "f0", "type": "textarea", "label": "What my mind did during the wait, honestly:"}, {"id": "f1", "type": "textarea", "label": "The kind of person I want to be in a room like that:"}, {"id": "f2", "type": "textarea", "label": "One small action that fits that value and is possible in a plastic chair:"}, {"id": "f3", "type": "textarea", "label": "What I did, and what the wait was like with a direction:"}, {"id": "f4", "type": "textarea", "label": "Where else in my week a dull wait could hold a value:"}]'::jsonb, array['values', 'committed action', 'core ACT']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('willing-to-let-the-phone-ring-out-page', 'Willing to Let the Phone Ring Out Page', 'act'::resource_kind, 'A willingness page for the client who answers every call and message instantly to quiet the pull of being needed.', 'Use it to help the client make room for the discomfort of an unanswered ring.', array['Adults', 'Teens']::text[], 'One week of practice', 'Some clients answer every call on the first ring not from eagerness but from the discomfort of letting it go. The page asks what shows up in the body when a call rings unanswered, what the mind says it means, and what the client is willing to feel for the sake of a value (a finished dinner, a full conversation with the person in front of them). Then one experiment: let a non-urgent call ring out and call back in an hour. Agree the exceptions in session so this is never confused with ignoring an emergency. Turning the phone off entirely is avoidance, not willingness.', '[{"id": "f0", "type": "textarea", "label": "What happens in my body when a call rings and I do not answer:"}, {"id": "f1", "type": "textarea", "label": "What my mind says it means if I let it ring out:"}, {"id": "f2", "type": "textarea", "label": "What I would be making room for, and the value it serves:"}, {"id": "f3", "type": "textarea", "label": "The call I am willing to let ring out this week, and who is excepted from this:"}, {"id": "f4", "type": "textarea", "label": "What happened when I called back an hour later:"}, {"id": "f5", "type": "textarea", "label": "What the hour in between was like:"}]'::jsonb, array['willingness', 'boundaries', 'committed action']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('breath-fog-on-a-cold-window-present-moment-page', 'Breath Fog on a Cold Window Present Moment Page', 'act'::resource_kind, 'A present-moment page built on a cold morning window: breathe on the glass, watch the fog bloom and fade, repeat.', 'Use it to give the client a winter anchor that takes one minute and no equipment.', array['Adults', 'Teens']::text[], 'Two minutes daily', 'A cold window is a ready-made mindfulness object: breathe on it and a cloud appears, fades, and is gone. The page asks the client to do it five times, noticing the warmth of the breath, the shape of the fog, the moment it disappears, and where the mind went in between. Then one line on what the fading cloud reminds them of about their own feelings. It is a small, playful anchor that works at a bus stop or a kitchen sink. Watch for the client who treats the fog''s fading as a lesson they must feel deeply; the noticing is enough.', '[{"id": "f0", "type": "textarea", "label": "What I noticed in the breath, the fog and the glass over five rounds:"}, {"id": "f1", "type": "textarea", "label": "Where my mind went between breaths, and how I came back:"}, {"id": "f2", "type": "textarea", "label": "What the fog fading reminds me of in my own feelings, if anything:"}, {"id": "f3", "type": "textarea", "label": "Where I could do this on an ordinary cold morning:"}, {"id": "f4", "type": "textarea", "label": "How I felt after two minutes, in a few words:"}]'::jsonb, array['present moment', 'mindfulness', 'core ACT']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('chessboard-self-under-the-holiday-argument-page', 'Chessboard Self Under the Holiday Argument Page', 'act'::resource_kind, 'A self-as-context page using the chessboard metaphor for the family argument that keeps replaying after the holiday.', 'Use it to give the client a place to stand that is not one of the pieces in the fight.', array['Adults', 'Teens']::text[], '20 minutes in session', 'After a family argument, the client often lives as one of the pieces: the one who was right, the one who was wronged, the one who should have stayed quiet. The chessboard metaphor offers another place: the board that holds every piece and is not moved by the game. The page asks the client to name the pieces (their own thoughts and the relatives'' lines), then to describe the argument from the board''s point of view, and what the board can do that no piece can. Watch for the client who hears the board as indifference; it is the opposite, a place to hold the whole game without being knocked over.', '[{"id": "f0", "type": "textarea", "label": "The pieces on my side of the board (my thoughts and feelings about the argument):"}, {"id": "f1", "type": "textarea", "label": "The pieces on the other side (what they said, what I think they think):"}, {"id": "f2", "type": "textarea", "label": "The argument described from the board''s point of view, holding every piece:"}, {"id": "f3", "type": "textarea", "label": "What the board can do that no single piece can:"}, {"id": "f4", "type": "textarea", "label": "A moment this week I could step onto the board instead of a square:"}]'::jsonb, array['self-as-context', 'metaphor', 'family']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('dear-man-for-returning-the-gift-without-the-receipt-card', 'DEAR MAN for Returning the Gift Without the Receipt Card', 'dbt'::resource_kind, 'A DEAR MAN card for the return counter when the gift is wrong and the receipt is gone.', 'Use it to rehearse a low-stakes ask at a counter where the client usually gives up.', array['Adults', 'Teens']::text[], '15 minutes to prepare', 'The return counter is a good training ground for DEAR MAN: a clear ask, a policy that may say no, a line of people, and a client who tends to walk away with the wrong sweater. The card walks through Describe, Express, Assert, Reinforce, then stays Mindful (broken record), Appears confident and Negotiates (store credit, exchange, a smaller item). Rehearse the Assert line aloud in session with you as the clerk. Watch for the client who apologizes three times before asking; count the apologies together and try it with zero.', '[{"id": "f0", "type": "textarea", "label": "Describe: what I will say about the item and the missing receipt, just the facts:"}, {"id": "f1", "type": "textarea", "label": "Express: how I will say what I am hoping for without apologizing for it:"}, {"id": "f2", "type": "textarea", "label": "Assert: my clear ask, in one sentence:"}, {"id": "f3", "type": "textarea", "label": "Reinforce: what the store gets if it helps (a returning customer, a quick line):"}, {"id": "f4", "type": "textarea", "label": "Mindful: the line I repeat if they say no the first time:"}, {"id": "f5", "type": "textarea", "label": "Negotiate: what I will accept instead (credit, exchange, partial):"}]'::jsonb, array['DEAR MAN', 'interpersonal effectiveness', 'assertiveness']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('wise-mind-before-accepting-the-overtime-shift-card', 'Wise Mind Before Accepting the Overtime Shift Card', 'dbt'::resource_kind, 'A wise mind card for the text asking the client to cover another shift, before the reflexive yes.', 'Use it to put a breath between the manager''s text and the client''s answer.', array['Adults', 'Teens']::text[], 'Five minutes when the text arrives', 'Extra shifts are accepted in emotion mind (guilt, fear of being passed over) or reasonable mind (the money, the hours) in the seconds after the text. The card asks the client to write what each mind says, then to drop into wise mind with a slow breath and ask what they know to be true about their week, their body and the people waiting at home. The answer may still be yes; the card is about who answers. Watch for the client who always finds wise mind agreeing with the manager; that is worth a gentle look in session.', '[{"id": "f0", "type": "textarea", "label": "The text, and what I felt in the first three seconds:"}, {"id": "f1", "type": "textarea", "label": "What emotion mind says about saying no:"}, {"id": "f2", "type": "textarea", "label": "What reasonable mind says about the money and the hours:"}, {"id": "f3", "type": "textarea", "label": "After a slow breath, what wise mind knows about my week, my body and the people at home:"}, {"id": "f4", "type": "textarea", "label": "My answer, and how I will say it:"}, {"id": "f5", "type": "textarea", "label": "How I feel an hour after sending it:"}]'::jsonb, array['wise mind', 'work', 'decisions']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('half-smile-while-the-printer-jams-again-card', 'Half Smile While the Printer Jams Again Card', 'dbt'::resource_kind, 'A half smile card for the office printer, the parking machine and every other device that fails at the worst moment.', 'Use it to give the client a body-first move for small mechanical frustrations.', array['Adults', 'Teens']::text[], 'One minute, many times a week', 'The jammed printer is a perfect rehearsal space for half smile: a frustration that is real, small, and over in minutes, happening in front of coworkers. The card asks the client to notice the jaw and shoulders at the moment of the jam, let the face soften into the barest smile, breathe once, and only then open the tray. The log asks what the frustration did in the body with and without the half smile. Watch for the client who feels foolish smiling at a machine; name that it is for the face, not the printer.', '[{"id": "f0", "type": "textarea", "label": "The device that fails most often in my week, and how my face and shoulders react:"}, {"id": "f1", "type": "textarea", "label": "What I noticed when I let the half smile come before touching the machine:"}, {"id": "f2", "type": "textarea", "label": "How long the frustration lasted with the half smile versus without:"}, {"id": "f3", "type": "textarea", "label": "What my coworkers did or did not notice:"}, {"id": "f4", "type": "textarea", "label": "One other small frustration I will try this on:"}]'::jsonb, array['half smile', 'distress tolerance', 'work']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-of-the-snow-day-with-no-childcare-card', 'Radical Acceptance of the Snow Day With No Childcare Card', 'dbt'::resource_kind, 'A radical acceptance card for the morning school is canceled and every plan for the day collapses with it.', 'Use it to help the client stop fighting the morning and start reshaping it.', array['Adults']::text[], '10 minutes on the morning itself', 'A surprise school closure takes the whole day''s plan away in one text at six in the morning, and the first hour is often spent arguing with the fact. The card asks the client to write the fact plainly, list what they are fighting (the unfairness, the meeting, the boss), notice where the fight sits in the body, and say the turning-the-mind sentence. Then the rebuilt morning in three lines. It is not approval of the snow; it is the end of the argument with it. Watch for the client who accepts it and then punishes themselves with productivity all day.', '[{"id": "f0", "type": "textarea", "label": "The fact, written plainly: school is closed and I am the childcare:"}, {"id": "f1", "type": "textarea", "label": "What I am fighting about it, and who I am angry at:"}, {"id": "f2", "type": "textarea", "label": "Where the fight sits in my body:"}, {"id": "f3", "type": "textarea", "label": "My sentence for turning the mind toward the day I actually have:"}, {"id": "f4", "type": "textarea", "label": "The rebuilt morning in three lines:"}, {"id": "f5", "type": "textarea", "label": "What I will let go of today, by name:"}]'::jsonb, array['radical acceptance', 'parenting', 'distress tolerance']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('observe-and-describe-the-lost-package-feeling-card', 'Observe and Describe the Lost Package Feeling Card', 'dbt'::resource_kind, 'An observe-and-describe card for the surge when a delivery goes missing, practiced before the angry call.', 'Use it to slow the client down between the empty porch and the phone.', array['Adults', 'Teens']::text[], 'Five minutes in the moment', 'A missing package produces a sharp, specific surge: injustice, helplessness, and an urge to call someone and make it their fault. The card asks the client to observe the body before anything else (heat, jaw, hands), describe the emotion in plain words without the story, and name the urge without acting on it. Only then do they write the call they will make. The difference between the call written before and after the card is usually the point of the exercise. Watch for the client who skips to the describing and leaves out the body; the body is where the surge lives.', '[{"id": "f0", "type": "textarea", "label": "Observe: what I notice in my body in the first minute:"}, {"id": "f1", "type": "textarea", "label": "Describe: the emotion in plain words, without the story of whose fault it is:"}, {"id": "f2", "type": "textarea", "label": "The urge, named but not acted on:"}, {"id": "f3", "type": "textarea", "label": "The call I would have made in the first minute:"}, {"id": "f4", "type": "textarea", "label": "The call I will make after the card:"}, {"id": "f5", "type": "textarea", "label": "What was different about how I was treated on the phone:"}]'::jsonb, array['observe and describe', 'mindfulness', 'core DBT']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('thermostat-setting-winter-truce-for-partners', 'Thermostat Setting Winter Truce for Partners', 'couples'::resource_kind, 'A couples truce for the thermostat war, with both partners'' comfort numbers, the house rule and the layers plan.', 'Use it to end a nightly argument that is really about whose comfort counts.', array['Couples']::text[], '20 minutes', 'The thermostat argument is small, repeated and oddly loaded: each partner hears the other''s number as a judgment on their body or their frugality. The truce asks each partner for their honest comfortable number, what the argument has been about underneath (money, being cold, being heard), a shared number or schedule they can both live with, and what each will do for their own comfort within it (a heated blanket, a fan, a sweater). Both partners write their own part. Watch for the partner who agrees and then quietly changes the dial at night; that is the thing to talk about, not a crime.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my honest comfortable number, and what the argument has really been about for me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: my honest comfortable number, and what the argument has really been about for me:"}, {"id": "f2", "type": "textarea", "label": "Our shared number or schedule for the season:"}, {"id": "f3", "type": "textarea", "label": "Partner A: what I will do for my own comfort within the rule:"}, {"id": "f4", "type": "textarea", "label": "Partner B: what I will do for my own comfort within the rule:"}, {"id": "f5", "type": "textarea", "label": "What we will say instead of changing the dial in secret:"}]'::jsonb, array['couples', 'fairness', 'conflict']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('holiday-card-photo-and-message-pact-for-partners', 'Holiday Card Photo and Message Pact for Partners', 'couples'::resource_kind, 'A couples pact for the yearly card: who is in the photo, what the message says and who does the work of sending it.', 'Use it to stop a small yearly ritual from becoming a yearly fight.', array['Couples']::text[], '20 minutes', 'The holiday card looks trivial and is not: it is the couple''s public face for a year, and one partner usually carries all of it while the other critiques the result. The pact asks each partner what they want the card to say about their family, what they dread about the process, and which parts they will own (photo, list, message, stamps). A box for what to do about the relatives who always complain about being left off keeps the pact honest. Watch for the partner who says they do not care and then does; invite them to say one thing they want.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I want this year''s card to say about us, and what I dread about making it:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I want this year''s card to say about us, and what I dread about making it:"}, {"id": "f2", "type": "textarea", "label": "Who owns the photo, the list, the message and the stamps:"}, {"id": "f3", "type": "textarea", "label": "What we will do about the relative who complains every year:"}, {"id": "f4", "type": "textarea", "label": "Our deadline, and what happens if we miss it (no card is an allowed answer):"}]'::jsonb, array['couples', 'holidays', 'planning']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('one-partners-overtime-season-check-in-plan-for-partners', 'One Partner''s Overtime Season Check-In Plan for Partners', 'couples'::resource_kind, 'A couples plan for the stretch when one partner''s job takes everything, with check-ins that fit the schedule.', 'Use it to keep the couple connected through a busy season without a fight about the hours.', array['Couples']::text[], '25 minutes before the season starts', 'Tax season, retail December, harvest, a product launch: one partner disappears into work and the other keeps the house and the resentment. The plan asks the working partner what the season really looks like and what they can promise, and the home partner what they most need and what they can carry alone for a while. Together they set the smallest check-in that fits (a text at lunch, ten minutes before sleep), an end date, and what they will do the week after. Watch for the home partner who agrees to everything and then keeps score; the plan should include what they get back.', '[{"id": "f0", "type": "textarea", "label": "Working partner: what the season actually looks like, and what I can honestly promise:"}, {"id": "f1", "type": "textarea", "label": "Home partner: what I most need from you in it, and what I can carry alone for a while:"}, {"id": "f2", "type": "textarea", "label": "Our smallest daily check-in, and when:"}, {"id": "f3", "type": "textarea", "label": "The end date, and what we will do the week after it:"}, {"id": "f4", "type": "textarea", "label": "What each of us will say when the other one slips:"}]'::jsonb, array['couples', 'work', 'connection']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('weekend-morning-who-sleeps-in-rotation-for-partners', 'Weekend Morning Who Sleeps In Rotation for Partners', 'couples'::resource_kind, 'A couples rotation for weekend mornings so each partner gets a slow start, with the handoff spelled out.', 'Use it to replace the silent contest over who gets up with a schedule both can count on.', array['Couples']::text[], '15 minutes', 'The weekend sleep-in becomes a contest when nobody says who gets it, and the partner who gets up keeps a quiet ledger. The rotation asks each partner how much a slow morning matters to them, which day they want, what the up partner handles (kids, dog, coffee), how late is too late, and how the handoff happens without a passive-aggressive door. Both partners sign their own part. Watch for the partner who insists they do not need it and then resents the other''s lie-in; ask them to take a turn anyway.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how much a slow morning matters to me, and which day I want:"}, {"id": "f1", "type": "textarea", "label": "Partner B: how much a slow morning matters to me, and which day I want:"}, {"id": "f2", "type": "textarea", "label": "What the up partner handles, and how late the sleeping partner may sleep:"}, {"id": "f3", "type": "textarea", "label": "How the handoff happens (a knock, a coffee, a time):"}, {"id": "f4", "type": "textarea", "label": "What we do on a weekend when the plan breaks:"}]'::jsonb, array['couples', 'fairness', 'sleep']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('secret-spending-and-gift-surprises-money-talk-for-partners', 'Secret Spending and Gift Surprises Money Talk for Partners', 'couples'::resource_kind, 'A couples money talk for the season when surprises and hidden purchases blur the line between a gift and a secret.', 'Use it to let a couple agree where the surprise ends and the secret begins.', array['Couples']::text[], '30 minutes', 'Gift season gives every couple a reason to hide a purchase, and for some couples that reopens an old wound about money kept out of sight. The talk asks each partner what counts as a surprise and what counts as a secret, the amount above which they want to be told, how they each felt the last time a hidden purchase came to light, and a rule for the season. Both partners write their own answers before reading the other''s. Watch for the partner whose definition of surprise expands to cover everything; that is the conversation.', '[{"id": "f0", "type": "textarea", "label": "Partner A: for me, a surprise is… and a secret is…"}, {"id": "f1", "type": "textarea", "label": "Partner B: for me, a surprise is… and a secret is…"}, {"id": "f2", "type": "textarea", "label": "The amount above which each of us wants to be told, even in gift season:"}, {"id": "f3", "type": "textarea", "label": "How I felt the last time a hidden purchase came to light (each partner):"}, {"id": "f4", "type": "textarea", "label": "Our rule for this season, in one sentence:"}, {"id": "f5", "type": "textarea", "label": "How we will check in on it in January:"}]'::jsonb, array['couples', 'money', 'trust']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('paper-towel-tube-telescope-spot-the-good-play', 'Paper Towel Tube Telescope Spot the Good Play', 'kids'::resource_kind, 'A kids play tool: a decorated paper towel tube telescope used to spot one good thing in each room of the house.', 'Use it to give a child a playful way to shift attention toward what is going well.', array['Children']::text[], '20 minutes to make, then a daily sweep', 'The child decorates a paper towel tube as a telescope, then goes room to room looking through it for one good thing in each (a pet asleep, a drawing on the fridge, a sibling being kind). The parent walks with them and writes or draws what the telescope found. On hard days the parent hands over the telescope and asks for one find, not a mood change. In session, ask the child what the telescope is good at seeing and what it is not. Watch for the parent who uses the telescope to argue a sad child out of sadness; the telescope finds things, it does not fix feelings.', '[{"id": "f0", "type": "textarea", "label": "Draw or decorate your telescope here:"}, {"id": "f1", "type": "textarea", "label": "What my telescope spotted in each room today:"}, {"id": "f2", "type": "textarea", "label": "The hardest room to find something good in, and what I finally found:"}, {"id": "f3", "type": "textarea", "label": "Parent: what I noticed about my child''s mood before and after the sweep:"}, {"id": "f4", "type": "textarea", "label": "Something my telescope spotted that I want to remember:"}]'::jsonb, array['children', 'play', 'gratitude']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('pipe-cleaner-worry-bug-squish-and-reshape-craft', 'Pipe Cleaner Worry Bug Squish and Reshape Craft', 'kids'::resource_kind, 'A kids craft where a worry becomes a pipe cleaner bug that can be squished, stretched and bent into something else.', 'Use it to let a child handle a worry as something bendable rather than fixed.', array['Children']::text[], '20 minutes', 'The child twists pipe cleaners into a bug and gives it the worry''s name and its loudest line. Then they experiment: squish it small, stretch it long, bend it into a flower or a bracelet, and notice that the same wire makes all of them. The parent helps with the twisting and asks, each time, what the bug sounds like now. In session, use it to talk about worries changing size depending on the day. Watch for the child who wants to destroy the bug; redirect to reshaping, since the worry will be back and the point is that it can be shaped.', '[{"id": "f0", "type": "textarea", "label": "Draw your worry bug and write what it says:"}, {"id": "f1", "type": "textarea", "label": "What happened when you squished it small:"}, {"id": "f2", "type": "textarea", "label": "What happened when you stretched it long:"}, {"id": "f3", "type": "textarea", "label": "What you bent it into instead, and what it says now:"}, {"id": "f4", "type": "textarea", "label": "Parent: what my child said about the worry while their hands were busy:"}]'::jsonb, array['children', 'craft', 'worry']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('cotton-ball-snowman-melt-away-mad-play', 'Cotton Ball Snowman Melt Away Mad Play', 'kids'::resource_kind, 'A kids play tool: build a cotton ball snowman for the mad feeling, then warm it with breath until it is ready to come apart.', 'Use it to give a young child a picture of anger building up and melting down.', array['Children']::text[], '15 minutes', 'The child stacks cotton balls or glues them to paper to make a snowman for the mad feeling, giving it a face and naming what made it. Then they breathe slow warm breaths on it, as if melting it, and pull one cotton ball away with each breath until the snowman is a puddle. The parent counts the breaths and asks what the mad feeling is doing in the child''s body as the snowman shrinks. In session, ask what makes the snowman grow back. Watch for the parent who hurries the melting; one ball per breath is the whole exercise.', '[{"id": "f0", "type": "textarea", "label": "Draw your mad snowman and write what made it:"}, {"id": "f1", "type": "textarea", "label": "How many warm breaths it took to melt it:"}, {"id": "f2", "type": "textarea", "label": "What the mad feeling did in your body as the snowman got smaller:"}, {"id": "f3", "type": "textarea", "label": "What makes your snowman grow back:"}, {"id": "f4", "type": "textarea", "label": "Parent: when I could use the melting breaths with my child this week:"}]'::jsonb, array['children', 'play', 'anger']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('toilet-paper-roll-binoculars-spot-a-calm-thing-play', 'Toilet Paper Roll Binoculars Spot a Calm Thing Play', 'kids'::resource_kind, 'A kids play tool: taped toilet paper roll binoculars for finding one calm thing in a loud or busy place.', 'Use it to give a child a grounding move disguised as an explorer''s game.', array['Children']::text[], '15 minutes to make, then as needed', 'Two toilet paper rolls taped side by side become binoculars the child decorates and carries. The job is to find one calm thing wherever they are (a slow ceiling fan, a plant, a sleeping dog, a cloud) and describe it in three words. The parent keeps the binoculars in the bag for the store, the waiting room or the loud restaurant and hands them over before the meltdown, not after. In session, practice finding a calm thing in the office. Watch for the parent who uses them as a reward or a punishment; they are a tool, available any time.', '[{"id": "f0", "type": "textarea", "label": "Decorate your binoculars here:"}, {"id": "f1", "type": "textarea", "label": "Calm things I spotted this week, and where:"}, {"id": "f2", "type": "textarea", "label": "Three words for my favorite calm thing:"}, {"id": "f3", "type": "textarea", "label": "Parent: the place my child most needs the binoculars, and where I will keep them:"}, {"id": "f4", "type": "textarea", "label": "Parent: what happened the first time I handed them over early:"}]'::jsonb, array['children', 'grounding', 'play']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('blanket-fort-password-feelings-word-play', 'Blanket Fort Password Feelings Word Play', 'kids'::resource_kind, 'A kids play tool: a blanket fort whose password is one feeling word, changed every time someone wants to come in.', 'Use it to make naming a feeling the ticket into a cozy place.', array['Children']::text[], '30 minutes', 'The child and parent build a blanket fort, and the rule is that anyone entering must say a password, which is a feeling word, and the child decides whether it is a new one each time. The parent takes turns being the guard and the visitor, modeling feelings beyond happy and sad (nervous, proud, left out, cozy). Inside the fort, whoever enters gets one question about their password word. In session, ask the child for the fort''s favorite passwords. Watch for the parent who corrects a child''s unusual feeling word; every word that gets someone in is a good password.', '[{"id": "f0", "type": "textarea", "label": "Draw your fort and write its first password:"}, {"id": "f1", "type": "textarea", "label": "All the passwords we used today:"}, {"id": "f2", "type": "textarea", "label": "A feeling word I had never used before:"}, {"id": "f3", "type": "textarea", "label": "Parent: a feeling word I shared that surprised my child:"}, {"id": "f4", "type": "textarea", "label": "Parent: how the fort could become our way to talk about a hard day:"}]'::jsonb, array['children', 'emotion identification', 'play']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('blind-shape-rope-circle-group-game', 'Blind Shape Rope Circle Group Game', 'game'::resource_kind, 'A group game where blindfolded players holding one rope must form a square, then a triangle, using only words.', 'Use it to let a group practice clear speaking, listening and patience under mild frustration.', array['Groups', 'Adults', 'Teens']::text[], '25 minutes', 'Rules: the group holds a long rope loop, closes their eyes (or wears blindfolds), and must form a square in three minutes using words only, with no one letting go. Then a triangle, then a star. The leader times each shape and calls time; eyes open to see the result. Turns: rotate who may speak first each round so the quiet members lead once. Debrief: who talked, who listened, what frustration did to voices, and what the group did when two plans competed. Watch for the player who grabs control each round; ask the group what it was like to be led by them and let them hear it kindly.', '[{"id": "f0", "type": "textarea", "label": "What my role in the rope turned out to be (talker, listener, follower, peacemaker):"}, {"id": "f1", "type": "textarea", "label": "What happened to my voice and patience when the shape was not working:"}, {"id": "f2", "type": "textarea", "label": "What the group did when two plans competed:"}, {"id": "f3", "type": "textarea", "label": "One thing someone else said that helped the shape form:"}, {"id": "f4", "type": "textarea", "label": "What I will do differently the next time a group is stuck with no leader:"}]'::jsonb, array['group', 'communication', 'teamwork']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('marshmallow-tower-teamwork-build-game', 'Marshmallow Tower Teamwork Build Game', 'game'::resource_kind, 'A group game where small teams build the tallest freestanding tower from marshmallows and dry spaghetti against the clock.', 'Use it to surface how each member handles pressure, failure and credit in a low-stakes build.', array['Groups', 'Adults', 'Teens']::text[], '30 minutes', 'Rules: teams of three or four get twenty marshmallows, twenty sticks of dry spaghetti and ten minutes to build the tallest tower that stands on its own for ten seconds. Collapses are allowed and expected. Turns: in the second round each team must rotate who places the next piece. Debrief: who planned and who dove in, what happened to the team when the tower fell, who took credit and who took blame, and what the second round''s forced turns changed. Watch for the team that blames one builder for the collapse; the debrief is for noticing that reflex, not confirming it.', '[{"id": "f0", "type": "textarea", "label": "What I did first when the timer started (plan, grab, watch):"}, {"id": "f1", "type": "textarea", "label": "What happened in my team when the tower fell:"}, {"id": "f2", "type": "textarea", "label": "How the forced turns in round two changed how we built:"}, {"id": "f3", "type": "textarea", "label": "Who I noticed taking credit or blame, including me:"}, {"id": "f4", "type": "textarea", "label": "What I learned about how I work under a timer:"}]'::jsonb, array['group', 'teamwork', 'stress']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('mirror-mirror-partner-movement-copy-game', 'Mirror Mirror Partner Movement Copy Game', 'game'::resource_kind, 'A partner game where one player leads slow movements and the other mirrors them exactly, then they switch, then nobody leads.', 'Use it to practice attunement, following and the discomfort of being watched.', array['Groups', 'Adults', 'Teens']::text[], '20 minutes', 'Rules: partners face each other at arm''s length. One leads with slow movements of hands, face and body; the other mirrors as exactly as they can, with no talking. After two minutes, switch. In the third round, nobody is the leader and the pair tries to move together anyway. Turns: rotate partners once so everyone works with someone they know less. Debrief: what leading felt like, what following felt like, how the leaderless round went, and who found being watched the hardest part. Watch for the pair that speeds up to make it funny; slow is where the exercise lives.', '[{"id": "f0", "type": "textarea", "label": "What leading felt like, and what following felt like:"}, {"id": "f1", "type": "textarea", "label": "What happened in the round where nobody led:"}, {"id": "f2", "type": "textarea", "label": "What being watched that closely was like for me:"}, {"id": "f3", "type": "textarea", "label": "Something I noticed about my partner that I would not have in conversation:"}, {"id": "f4", "type": "textarea", "label": "Where in my life I lead when I could follow, or follow when I could lead:"}]'::jsonb, array['group', 'connection', 'mindfulness']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('zip-zap-zop-focus-circle-game', 'Zip Zap Zop Focus Circle Game', 'game'::resource_kind, 'A fast circle game where players pass energy with a clap and a word, in order, and restart when the pattern breaks.', 'Use it to warm up a group''s attention and make small mistakes ordinary.', array['Groups', 'Teens']::text[], '15 minutes', 'Rules: the circle passes a clap with a point and a word, in strict order (zip, then zap, then zop, then zip again), to anyone across the circle. Whoever receives passes it on with the next word. A wrong word or a hesitation breaks the pattern, and the group restarts from zip with no penalty. Turns: as it speeds up, add a second pass running at the same time. Debrief: what happened in the body before a turn, how it felt to break the pattern in front of everyone, and what the group did with the mistakes (groaned, laughed, blamed). Watch for the player who stops playing after one miss.', '[{"id": "f0", "type": "textarea", "label": "What happened in my body right before the clap came to me:"}, {"id": "f1", "type": "textarea", "label": "What it was like to break the pattern in front of everyone:"}, {"id": "f2", "type": "textarea", "label": "What the group did with mistakes, and how that felt:"}, {"id": "f3", "type": "textarea", "label": "How my attention changed when the second pass was added:"}, {"id": "f4", "type": "textarea", "label": "One place this week I could let a small mistake be ordinary:"}]'::jsonb, array['group', 'attention', 'play']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('twenty-questions-feeling-edition-game', 'Twenty Questions Feeling Edition Game', 'game'::resource_kind, 'A group guessing game where one player holds a feeling word and the circle has twenty yes-or-no questions to find it.', 'Use it to stretch a group''s feeling vocabulary and curiosity about each other''s experience.', array['Groups', 'Teens']::text[], '20 minutes', 'Rules: one player draws a feeling card (relieved, left out, smug, homesick, restless) and the circle asks up to twenty yes-or-no questions (does it show on your face, would you want company, does it come before or after something). The holder answers from their own experience of that feeling. Turns: a new holder each round; the guesser who names it draws next. Debrief: which questions got closest, which feelings were hardest to guess, and whether anyone was surprised by how someone else experiences a feeling. Nudge a group that only asks about intensity toward where it lives.', '[{"id": "f0", "type": "textarea", "label": "The feelings I held, and how many questions it took:"}, {"id": "f1", "type": "textarea", "label": "The question that got closest to my feeling:"}, {"id": "f2", "type": "textarea", "label": "A feeling someone else described differently from how I know it:"}, {"id": "f3", "type": "textarea", "label": "A feeling word I had never used before today:"}, {"id": "f4", "type": "textarea", "label": "How it felt to be asked about a feeling instead of told about it:"}]'::jsonb, array['group', 'emotion identification', 'play']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('crowded-mall-parking-garage-orientation-steps-sheet', 'Crowded Mall Parking Garage Orientation Steps Sheet', 'worksheet'::resource_kind, 'A pacing sheet for the dim, echoing parking garage, with an orientation routine the client runs before leaving the car.', 'Use it to give the client a steadying routine for a place that sets off the alarm before they are out of the car.', array['Adults']::text[], '10 minutes to plan, then each trip', 'Parking garages combine the things a stirred-up nervous system dislikes: low light, echoes, blind corners, strangers appearing. The sheet plans a routine the client runs before opening the door (name the level and the nearest exit sign, five slow breaths, feet on the floor, one line about today''s date and purpose), a rule for where to park (near the elevator, under a light) and what they will do if the alarm rises on the walk. Nothing here asks what the garage reminds them of; it is a stabilizing plan. For the client who avoids every garage, this sheet is a middle step, and pacing matters.', '[{"id": "f0", "type": "textarea", "label": "Where I will park, and why that spot:"}, {"id": "f1", "type": "textarea", "label": "My routine before I open the car door, step by step:"}, {"id": "f2", "type": "textarea", "label": "What I say to myself about where and when I am:"}, {"id": "f3", "type": "textarea", "label": "What I will do if the alarm rises on the walk (stop, breathe, name three things, keep walking or return):"}, {"id": "f4", "type": "textarea", "label": "Who I can text when I reach the store or the car:"}, {"id": "f5", "type": "textarea", "label": "How the trip went, and what I would change:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'pacing']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('sitting-facing-the-door-is-a-weakness-gentle-check-sheet', 'Sitting Facing the Door Is a Weakness Gentle Check Sheet', 'cbt'::resource_kind, 'A gentle check sheet for the belief that needing to face the door in a restaurant means something is wrong with the client.', 'Use it to loosen the shame around a protective habit without pushing the client to drop it.', array['Adults']::text[], '20 minutes in session', 'Many clients with a trauma history choose the seat facing the door and then judge themselves for it. The sheet asks what the habit is, what the client''s mind says it means about them, what the habit actually does for them (a sense of knowing what is coming), and what they would think of a friend with the same seat. The last box asks whether they want to change the habit at all right now; the sheet is about the self-judgment, not the chair. Keep it in session, and watch for the client who hears the check as pressure to sit with their back to the room.', '[{"id": "f0", "type": "textarea", "label": "The habit, and when I notice myself doing it:"}, {"id": "f1", "type": "textarea", "label": "What my mind says it means about me:"}, {"id": "f2", "type": "textarea", "label": "What the habit actually gives me:"}, {"id": "f3", "type": "textarea", "label": "What I would think of a friend who did the same thing:"}, {"id": "f4", "type": "textarea", "label": "A kinder sentence about the habit, in my own words:"}, {"id": "f5", "type": "textarea", "label": "Do I want to change it at all right now? Either answer is fine:"}]'::jsonb, array['PTSD and trauma', 'self-criticism', 'stabilizing']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('hypervigilance-as-a-lighthouse-beam-that-can-dim-page', 'Hypervigilance as a Lighthouse Beam That Can Dim Page', 'act'::resource_kind, 'An acceptance page that pictures constant scanning as a lighthouse beam: built for a storm, still sweeping, able to be dimmed.', 'Use it to let the client hold their alertness with respect rather than fight it.', array['Adults']::text[], '20 minutes in session', 'Clients often want their scanning gone, and fight it, which brightens the beam. The page offers the lighthouse: it was built for a storm, it still sweeps, and it does not have to be demolished to be dimmed. The client describes what the beam watches for, what it has protected, what it costs them now, and what a dimmer setting would look like on an ordinary evening. The exercise stays with the present (where the beam can rest tonight) and never asks about the storm it was built for. Watch for the client who takes dimming as a demand; the page is permission, not a task.', '[{"id": "f0", "type": "textarea", "label": "What my beam watches for, and what it has protected me from:"}, {"id": "f1", "type": "textarea", "label": "What the beam costs me on an ordinary evening:"}, {"id": "f2", "type": "textarea", "label": "What a dimmer setting would look like at home tonight:"}, {"id": "f3", "type": "textarea", "label": "One place or person around whom the beam already dims a little:"}, {"id": "f4", "type": "textarea", "label": "A sentence that thanks the lighthouse and lets it rest for an hour:"}]'::jsonb, array['PTSD and trauma', 'acceptance', 'metaphor']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('observe-and-describe-the-rooms-four-corners-card', 'Observe and Describe the Room''s Four Corners Card', 'dbt'::resource_kind, 'A grounding card: find the four corners of the room, describe one plain fact about each, then return to the body.', 'Use it to give the client a thirty-second anchor that works in any room.', array['Adults']::text[], 'One minute, as needed', 'When the body starts to leave the present, finding the room''s corners gives the eyes somewhere ordinary to go. The card walks the client clockwise: locate each corner, describe one fact about it in a plain sentence (the ceiling meets two white walls, there is a cord running down), then notice the feet and the chair. The log asks how long it took to feel the chair again. Practice it in the office until it is automatic, so it is available in a store or a meeting. Watch for the client who narrates the corners while still somewhere else; slow them to one corner per breath.', '[{"id": "f0", "type": "textarea", "label": "Corner one, one plain fact:"}, {"id": "f1", "type": "textarea", "label": "Corner two, one plain fact:"}, {"id": "f2", "type": "textarea", "label": "Corner three, one plain fact:"}, {"id": "f3", "type": "textarea", "label": "Corner four, one plain fact:"}, {"id": "f4", "type": "textarea", "label": "Now my feet and the chair: what I notice:"}, {"id": "f5", "type": "textarea", "label": "How long it took to feel the chair again, and where I used this today:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'observe and describe']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('loud-movie-scene-pause-signal-plan-for-partners', 'Loud Movie Scene Pause Signal Plan for Partners', 'couples'::resource_kind, 'A couples plan for the sudden loud or violent movie scene at home, with a pause signal, a reset and a no-questions rule.', 'Use it to let a couple keep watching things together without the sofa becoming a test.', array['Couples']::text[], '20 minutes', 'A movie at home can turn in one scene, and the partner with a trauma history ends up either enduring it or leaving the room in silence. The plan asks that partner for the kinds of scenes that tend to set off the alarm and what helps in the minute after (pause, lights up, a hand, a few words about where they are), and the other partner for what they can offer. Together they set a pause signal, a no-questions rule for the moment itself, and when, if ever, they talk about it. Nothing asks for the story behind the alarm. The plan is for staying together, not shrinking the list of what they watch.', '[{"id": "f0", "type": "textarea", "label": "Partner with the alarm: the kinds of scenes that tend to set it off, and what helps in the minute after:"}, {"id": "f1", "type": "textarea", "label": "Other partner: what I can offer in that minute without turning it into a check-up:"}, {"id": "f2", "type": "textarea", "label": "Our pause signal, and what happens in the first minute after it:"}, {"id": "f3", "type": "textarea", "label": "Our no-questions rule for the moment, and when we may talk about it later:"}, {"id": "f4", "type": "textarea", "label": "How we pick what to watch so nobody is tested:"}]'::jsonb, array['PTSD and trauma', 'couples', 'safety']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('waiting-on-the-car-repair-estimate-worry-hours-plan-sheet', 'Waiting on the Car Repair Estimate Worry Hours Plan Sheet', 'worksheet'::resource_kind, 'A plan for the hours between dropping the car at the shop and the call with the estimate, when worry has nothing to work with.', 'Use it to give a client a schedule for a wait they cannot shorten.', array['Adults', 'Teens']::text[], '10 minutes at drop-off', 'Waiting for a repair estimate is pure uncertainty with a dollar sign attached, and the worry fills every hour until the call. The sheet asks for the worst-case number the mind is offering and the realistic range, then plans the wait hour by hour with one absorbing task per block, a rule for how often to check the phone, and the question the client will ask when the shop calls. The last box is the actual estimate next to the feared one. Watch for the client who plans the hours but calls the shop at every block; the check rule is where the practice is.', '[{"id": "f0", "type": "textarea", "label": "The number my mind is offering, and the range that is actually likely:"}, {"id": "f1", "type": "textarea", "label": "Hour by hour, what I will do while I wait (one absorbing thing per block):"}, {"id": "f2", "type": "textarea", "label": "How often I will check my phone, and what I will do instead between checks:"}, {"id": "f3", "type": "textarea", "label": "The question I will ask when they call:"}, {"id": "f4", "type": "textarea", "label": "The actual estimate, next to the feared one:"}, {"id": "f5", "type": "textarea", "label": "What this wait taught me about my worry''s numbers:"}]'::jsonb, array['anxiety', 'uncertainty', 'money']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('if-i-do-not-plan-every-detail-it-falls-apart-belief-sheet', 'If I Do Not Plan Every Detail It Falls Apart Belief Sheet', 'cbt'::resource_kind, 'A belief sheet for the planner whose anxiety says the trip, the party or the week collapses the moment one detail is left loose.', 'Use it to test the belief that over-planning is what holds everything together.', array['Adults', 'Teens']::text[], '25 minutes', 'Clients who plan every detail often credit the planning for every outcome that went well and never test the loose end. The sheet names the belief, asks how strongly it is held, lists the evidence for it and against it (including the times something unplanned went fine), and designs one experiment: leave one detail of a low-stakes plan unplanned and record what happens. A box for what the planning costs (sleep, enjoyment, the people being planned) rounds it out. Watch for the client who picks a detail that was never going to matter; choose the experiment together.', '[{"id": "f0", "type": "textarea", "label": "The belief in my words, and how strongly I hold it (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "Evidence that over-planning holds everything together:"}, {"id": "f2", "type": "textarea", "label": "Evidence against it, including unplanned things that went fine:"}, {"id": "f3", "type": "textarea", "label": "What the planning costs me and the people I plan for:"}, {"id": "f4", "type": "textarea", "label": "The one detail I will leave loose this week, in a low-stakes plan:"}, {"id": "f5", "type": "textarea", "label": "What happened, and the belief rated again:"}]'::jsonb, array['anxiety', 'behavioral experiment', 'perfectionism']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('worry-as-a-weather-app-forecasting-storms-daily-page', 'Worry as a Weather App Forecasting Storms Daily Page', 'act'::resource_kind, 'A defusion page that treats the worried mind as a weather app that forecasts storms every day regardless of the sky.', 'Use it to help the client check the app without canceling the picnic.', array['Adults', 'Teens']::text[], '15 minutes, then daily', 'A worried mind forecasts like a weather app that only knows one icon: storm, every day, with high confidence. The page asks the client to write the week''s forecasts as the app would show them (the storm, the percentage the mind offers, the suggested cancellation), then what the actual weather was. The practice is to notice the forecast, say thank you app, and look out the window. This is not arguing with the app; it is deciding how much to let it run the day. Watch for the client who wants to delete the app; the point is that it stays installed and the picnic happens anyway.', '[{"id": "f0", "type": "textarea", "label": "This week''s forecasts from my worry app, with its confidence percentages:"}, {"id": "f1", "type": "textarea", "label": "What the app suggested I cancel or carry:"}, {"id": "f2", "type": "textarea", "label": "What the actual weather turned out to be, forecast by forecast:"}, {"id": "f3", "type": "textarea", "label": "My line for when the app pings (thank you, and a look out the window):"}, {"id": "f4", "type": "textarea", "label": "One picnic I will go on this week while the app forecasts a storm:"}]'::jsonb, array['anxiety', 'defusion', 'metaphor']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('cope-ahead-for-the-phone-call-i-keep-postponing-card', 'Cope Ahead for the Phone Call I Keep Postponing Card', 'dbt'::resource_kind, 'A cope ahead card for the call the client has moved three times: the insurance company, the landlord, the relative.', 'Use it to rehearse the call so thoroughly that making it becomes the easier option.', array['Adults', 'Teens']::text[], '15 minutes, then the call', 'The postponed call grows heavier each time it is moved. Cope ahead asks the client to describe the call in detail (who, what they need, what they fear hearing), name the emotion and the skills they will use at each hard point (paced breathing before dialing, a script for the opening, a plan if put on hold or told no), then imagine the call from dialing to hanging up with the skills in place. Then they make the call within the day, ideally in session or right after. Watch for the client who rehearses so well they feel finished without dialing; the card ends at the dial tone.', '[{"id": "f0", "type": "textarea", "label": "The call: who, what I need, and what I am afraid of hearing:"}, {"id": "f1", "type": "textarea", "label": "The emotion I expect, and where it will show up in my body:"}, {"id": "f2", "type": "textarea", "label": "My opening line, written out:"}, {"id": "f3", "type": "textarea", "label": "The skill I will use if I am put on hold, told no, or asked something I do not know:"}, {"id": "f4", "type": "textarea", "label": "The call imagined start to finish with the skills in place, in a few lines:"}, {"id": "f5", "type": "textarea", "label": "When I will make it today, and what happened:"}]'::jsonb, array['anxiety', 'cope ahead', 'avoidance']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('uncertainty-mystery-box-guess-and-wait-game', 'Uncertainty Mystery Box Guess and Wait Game', 'game'::resource_kind, 'A group game where a sealed box is passed around and players sit with not knowing what is inside until the very end.', 'Use it to let a group feel the pull to resolve uncertainty and practice waiting it out.', array['Groups', 'Teens']::text[], '25 minutes', 'Rules: the leader seals an ordinary object in a box. Players shake it and write a guess, then the leader announces the box will not be opened for twenty minutes while the group plays another short game. Every five minutes, players rate their urge to know (0 to 10) and what their mind is doing. Turns: anyone may ask one yes-or-no question per round. At the end the box opens. Debrief: how the urge changed over time, what the mind did with the gap, who asked for hints and who refused, and what the opened box was like after all that. Name kindly the player who stops caring to escape the wait.', '[{"id": "f0", "type": "textarea", "label": "My first guess, and my urge to know at the start (0 to 10):"}, {"id": "f1", "type": "textarea", "label": "My urge at five, ten, fifteen and twenty minutes:"}, {"id": "f2", "type": "textarea", "label": "What my mind did with the not knowing (stories, deals, giving up):"}, {"id": "f3", "type": "textarea", "label": "Whether I asked for hints, and why or why not:"}, {"id": "f4", "type": "textarea", "label": "What opening the box was like after the wait, and where in my life I meet this same pull:"}]'::jsonb, array['anxiety', 'uncertainty', 'group']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('walk-to-the-mailbox-and-back-micro-step-sheet', 'Walk to the Mailbox and Back Micro Step Sheet', 'worksheet'::resource_kind, 'A behavioral activation micro step: out the door, to the mailbox, and back, logged daily for a week.', 'Use it to give a client in low mood a step that ends in success every time.', array['Adults', 'Teens']::text[], 'Three minutes daily for a week', 'When a client cannot face a walk, the mailbox is a destination small enough to reach. The sheet asks for the time of day, the predicted difficulty, the actual difficulty, and one thing noticed on the way (the cold, a neighbor, the mail itself), with a box for what the client told themselves at the door. The first week is not about adding distance; it is about a reliable yes. Watch for the client who extends to a full walk on day two and quits by day four; hold them to the mailbox until the week is done.', '[{"id": "f0", "type": "textarea", "label": "The time of day I will go, and what I will say to myself at the door:"}, {"id": "f1", "type": "textarea", "label": "Day by day: predicted difficulty, actual difficulty (0 to 10), and one thing I noticed:"}, {"id": "f2", "type": "textarea", "label": "What got in the way on the days I did not go:"}, {"id": "f3", "type": "textarea", "label": "How I felt in the five minutes after, compared with the five minutes before:"}, {"id": "f4", "type": "textarea", "label": "What the second week''s step might be, if I want one:"}]'::jsonb, array['depression', 'behavioral activation', 'routines']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('skipping-the-call-back-means-i-am-a-bad-friend-record', 'Skipping the Call Back Means I Am a Bad Friend Record', 'cbt'::resource_kind, 'A thought record for the unreturned call that low mood turns into proof of being a bad friend.', 'Use it to separate a missed call from a verdict on the client''s character.', array['Adults', 'Teens']::text[], '20 minutes', 'In low mood, a missed call back becomes evidence, and the evidence becomes a reason not to call. The record takes the situation, the hot thought (I am a bad friend), the emotion and its intensity, the evidence for and against, and the thinking traps at work (labeling, overgeneralizing, mind reading the friend). The balanced thought is written to be usable at the moment of dialing. The action step is the call, or a text that says the call is coming. Watch for the client who writes a balanced thought and still does not call; the record is finished when the friend hears from them.', '[{"id": "f0", "type": "textarea", "label": "The call I have not returned, and how long it has been:"}, {"id": "f1", "type": "textarea", "label": "The hot thought, and the emotion with its intensity (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "Evidence for the thought:"}, {"id": "f3", "type": "textarea", "label": "Evidence against it, including what this friend has forgiven before:"}, {"id": "f4", "type": "textarea", "label": "The thinking traps I can spot:"}, {"id": "f5", "type": "textarea", "label": "A balanced thought I could hold while dialing, and when I will call or text:"}]'::jsonb, array['depression', 'thought record', 'labeling']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('energy-as-a-phone-on-low-power-mode-not-dead-page', 'Energy as a Phone on Low Power Mode Not Dead Page', 'act'::resource_kind, 'An acceptance page that pictures low mood''s energy as a phone on low power mode: dimmed, slower, still able to do what matters.', 'Use it to let the client pick what runs on a low battery day instead of waiting for a full charge.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients in low mood often wait for the full charge before doing anything, and the charge does not come. The page offers low power mode: the screen dims, the background apps stop, and the phone still makes the call that matters. The client lists what their mind says they cannot do on low power, what the essential functions are (the ones tied to a value), and what they can let run in the background or not at all today. The debrief asks what making one essential call did to the battery. Watch for the client who reads the metaphor as permission to shut off entirely; low power mode is still on.', '[{"id": "f0", "type": "textarea", "label": "What my mind says I cannot do on a low battery day:"}, {"id": "f1", "type": "textarea", "label": "My essential functions today, the ones tied to something I care about:"}, {"id": "f2", "type": "textarea", "label": "What I will let stop running today without guilt:"}, {"id": "f3", "type": "textarea", "label": "The one essential thing I did, and what it did to the battery:"}, {"id": "f4", "type": "textarea", "label": "What a low power mode day could look like if I planned for it instead of fighting it:"}]'::jsonb, array['depression', 'acceptance', 'metaphor']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('build-mastery-by-changing-the-bedsheets-card', 'Build Mastery by Changing the Bedsheets Card', 'dbt'::resource_kind, 'A build mastery card for one competence task in a low week: strip the bed, wash the sheets, make it up fresh.', 'Use it to give the client a finished, physical job that ends in a better night.', array['Adults', 'Teens']::text[], 'One hour, once this week', 'Changing the sheets is a build mastery task with an unusual payoff: the client sleeps in the result. The card asks the client to break it into steps (strip, wash, dry, make), pick the day and the hour, predict how hard it will feel and how good the bed will feel, then log both. It also asks what they will say to the voice that says it does not matter. For a client with very low energy, split it across two days and count both as done. Watch for the client who adds the whole bedroom to the task; the card is the bed, nothing else.', '[{"id": "f0", "type": "textarea", "label": "The steps, and the day and hour I will start:"}, {"id": "f1", "type": "textarea", "label": "How hard I predict it will feel (0 to 10), and how good I predict the bed will feel:"}, {"id": "f2", "type": "textarea", "label": "What I will say to the voice that says it does not matter:"}, {"id": "f3", "type": "textarea", "label": "How hard it actually was, and what the bed was like that night:"}, {"id": "f4", "type": "textarea", "label": "Where mastery showed up in my body after it was done:"}]'::jsonb, array['depression', 'build mastery', 'routines']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('grocery-run-together-when-one-partner-cannot-start-plan', 'Grocery Run Together When One Partner Cannot Start Plan', 'couples'::resource_kind, 'A couples plan for the errand that will not begin when one partner''s mood is low, with the other partner''s role spelled out.', 'Use it to turn one stuck errand into something the couple does together without a lecture.', array['Couples']::text[], '15 minutes', 'When one partner is in a low stretch, the grocery run becomes a wall, and the other partner swings between doing it alone and pushing. The plan asks the low partner what the wall feels like and what kind of help gets them to the car (a time, a short list, company, no talking about it), and the other partner what they can offer and what they need to stop doing (reminders, sighs). They write a shared tiny version of the errand and a signal for when the low partner is in. Watch for the partner who turns the plan into another task to fail at; keep the list to five items.', '[{"id": "f0", "type": "textarea", "label": "Low partner: what the wall feels like, and what kind of help gets me to the car:"}, {"id": "f1", "type": "textarea", "label": "Other partner: what I can offer, and what I will stop doing:"}, {"id": "f2", "type": "textarea", "label": "Our tiny version of the errand (five items, one store, home in an hour):"}, {"id": "f3", "type": "textarea", "label": "The signal for I am in, and the signal for not today:"}, {"id": "f4", "type": "textarea", "label": "How we talk about it afterward, in two sentences or fewer:"}]'::jsonb, array['depression', 'couples', 'support']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('charging-station-one-place-for-every-device-setup-sheet', 'Charging Station One Place for Every Device Setup Sheet', 'worksheet'::resource_kind, 'A setup sheet for one charging spot where every device lives at night, ending the morning hunt for the dead phone or earbuds.', 'Use it to swap a daily scramble for a single external habit.', array['Adults', 'Teens']::text[], '30 minutes to set up, then two weeks of use', 'Lost and dead devices are a daily tax for a client with attention trouble, and willpower does not pay it; a place does. The sheet asks the client to list every device that goes missing, pick the one spot by the door or bedside where they already pause at night, list what they need (a power strip, a tray, labels), and set a cue (plugging in when the last alarm is set). The two-week log tracks nights the station was used and mornings nothing was missing. Watch for the client who designs the perfect station and never buys the power strip; the first step is the purchase.', '[{"id": "f0", "type": "textarea", "label": "Every device that goes missing or dies on me:"}, {"id": "f1", "type": "textarea", "label": "The one spot I already pass every night, and why it works:"}, {"id": "f2", "type": "textarea", "label": "What I need to buy or move to make the station real, and when I will do it:"}, {"id": "f3", "type": "textarea", "label": "My cue for plugging everything in:"}, {"id": "f4", "type": "textarea", "label": "Two-week log: nights I used the station, and mornings nothing was missing:"}, {"id": "f5", "type": "textarea", "label": "What I will change if it stops working:"}]'::jsonb, array['ADHD', 'routines', 'executive function']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('starting-at-midnight-works-best-for-me-belief-check-sheet', 'Starting at Midnight Works Best for Me Belief Check Sheet', 'cbt'::resource_kind, 'A belief check for the conviction that late-night, last-minute starts are when the client does their best work.', 'Use it to test a self-story about productivity against what the late nights actually produce and cost.', array['Adults', 'Teens']::text[], '25 minutes', 'Many clients with attention trouble believe they work best at midnight under deadline pressure, and the belief protects the pattern. The sheet names the belief, lists what the late starts have produced and cost (sleep, the next day, the panic, half-done work), and separates the part that is true (pressure helps them start) from the part that is not (midnight is the only pressure available). The experiment is one task started with an invented early deadline and a body double or timer. When the client defends the belief with one great midnight, ask for the other nine.', '[{"id": "f0", "type": "textarea", "label": "The belief in my words, and how strongly I hold it:"}, {"id": "f1", "type": "textarea", "label": "What my late starts have actually produced, good and half-done:"}, {"id": "f2", "type": "textarea", "label": "What they have cost me the next day:"}, {"id": "f3", "type": "textarea", "label": "The part of the belief that is true, and the part that is not:"}, {"id": "f4", "type": "textarea", "label": "One task I will start early this week with a made-up deadline and a timer or body double:"}, {"id": "f5", "type": "textarea", "label": "What happened, and the belief rated again:"}]'::jsonb, array['ADHD', 'task initiation', 'behavioral experiment']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('boring-task-as-a-toll-booth-on-the-road-to-what-matters-page', 'Boring Task as a Toll Booth on the Road to What Matters Page', 'act'::resource_kind, 'A values page that places the dull, avoided task as a toll booth on the road to something the client actually wants.', 'Use it to connect a boring task to a value so the client can pay the toll and keep driving.', array['Adults', 'Teens']::text[], '15 minutes', 'A boring task has no pull of its own for a mind that runs on interest, so it needs to borrow pull from somewhere. The page asks the client to name the task, the road it sits on (what it leads to that they care about), what the toll costs in minutes and discomfort, and what their mind says at the booth (turn around, take the long way). Then they pay the toll with a timer running and log what the road looked like on the other side. Watch for the client who cannot find a value behind the task; sometimes the honest answer is that the task is not on any road they want, and that is useful too.', '[{"id": "f0", "type": "textarea", "label": "The boring task, and how long I have been avoiding it:"}, {"id": "f1", "type": "textarea", "label": "The road it sits on: what it leads to that I actually care about:"}, {"id": "f2", "type": "textarea", "label": "What the toll costs in minutes and discomfort:"}, {"id": "f3", "type": "textarea", "label": "What my mind says at the booth:"}, {"id": "f4", "type": "textarea", "label": "I paid the toll with a timer running; what the other side of the booth was like:"}]'::jsonb, array['ADHD', 'values', 'task initiation']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('stop-skill-before-starting-a-third-project-card', 'STOP Skill Before Starting a Third Project Card', 'dbt'::resource_kind, 'A STOP skill card for the moment a new idea arrives while two projects are already half-finished.', 'Use it to put a pause between the exciting new idea and the abandoned old ones.', array['Adults', 'Teens']::text[], 'Two minutes when the idea strikes', 'The new idea arrives with more energy than the unfinished ones, and the client is three projects deep by evening. The STOP card runs Stop, Take a step back, Observe (what is unfinished, what the new idea promises, what the body feels), and Proceed mindfully with one of three choices: write the idea down for later, finish one small piece of an open project first, or start the new one on purpose with the others named. The log tracks the choice and how it felt the next day. Watch for the client who uses the card to shame themselves for having ideas; the ideas are not the problem.', '[{"id": "f0", "type": "textarea", "label": "Stop: the idea that just arrived, in one line:"}, {"id": "f1", "type": "textarea", "label": "Take a step back: what is unfinished right now:"}, {"id": "f2", "type": "textarea", "label": "Observe: what the new idea promises, and what my body is doing:"}, {"id": "f3", "type": "textarea", "label": "Proceed: my choice (park it, finish a piece first, or start it on purpose):"}, {"id": "f4", "type": "textarea", "label": "How I felt about the choice the next day:"}]'::jsonb, array['ADHD', 'STOP', 'impulsivity']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('hula-hoop-home-base-toy-return-play', 'Hula Hoop Home Base Toy Return Play', 'kids'::resource_kind, 'A kids play tool: a hula hoop on the floor is home base, and every toy out of it has to be run back before the song ends.', 'Use it to make returning things a game with a clear finish line and a parent who plays.', array['Children']::text[], '10 minutes at cleanup time', 'The child places a hula hoop (or a taped circle) on the floor as home base, picks a song, and races to run every toy from the room back into the hoop before the song ends. The parent plays too, with their own hoop for their own things, and calls out the countdown. Toys in the hoop at the end get put away together, and the child picks the next song. In session, ask the child what makes a good home base and where the toys usually hide. Watch for the parent who turns the song into a stopwatch and the game into a test; the hoop is for fun first, finishing second.', '[{"id": "f0", "type": "textarea", "label": "Draw your home base and the toys that live near it:"}, {"id": "f1", "type": "textarea", "label": "Our song, and how many toys made it home before it ended:"}, {"id": "f2", "type": "textarea", "label": "Where the toys hide that take the longest to find:"}, {"id": "f3", "type": "textarea", "label": "Parent: what I put in my own hoop while we played:"}, {"id": "f4", "type": "textarea", "label": "Parent: what cleanup was like with the hoop compared with without it:"}]'::jsonb, array['ADHD', 'children', 'play']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('football-watch-party-hand-drink-plan-sheet', 'Football Watch Party Hand Drink Plan Sheet', 'worksheet'::resource_kind, 'A plan for the watch party where everyone has a drink in hand, covering what is in the client''s hand, their seat and their exit.', 'Use it to let a client keep a social tradition while changing what they hold.', array['Adults']::text[], '15 minutes before the game', 'A watch party is hours long, loud and built around substance use, and the urges come in waves with the score. The sheet asks what the client will hold all afternoon and who will know why, where they will sit (near the door, away from the cooler), what they will say to the offer, what they will do during the urge spikes (a halftime walk, a text), and when they will leave regardless of the score. The debrief asks what the urges did over the hours. Watch for the client who plans to white-knuckle it without telling anyone; one ally in the room changes the afternoon.', '[{"id": "f0", "type": "textarea", "label": "What I will have in my hand all afternoon, and who in the room will know why:"}, {"id": "f1", "type": "textarea", "label": "Where I will sit, and why:"}, {"id": "f2", "type": "textarea", "label": "My line for the offer, said the same way every time:"}, {"id": "f3", "type": "textarea", "label": "What I will do at the urge spikes (halftime, the final minutes, the end):"}, {"id": "f4", "type": "textarea", "label": "When I leave regardless of the score, and who drives:"}, {"id": "f5", "type": "textarea", "label": "How the urges moved over the hours, in a few words:"}]'::jsonb, array['addiction', 'urges', 'planning']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('just-being-at-the-bar-does-not-count-permission-sheet', 'Just Being at the Bar Does Not Count Permission Sheet', 'cbt'::resource_kind, 'A sheet for the permission thought that says going to the bar without drinking is harmless, examined before the night out.', 'Use it to catch the seemingly harmless decision before it decides the evening.', array['Adults']::text[], '20 minutes before the night out', 'The thought that just being there is fine is often the first move in a chain that ends in substance use, and it is persuasive because it sounds reasonable. The sheet writes the thought, the evidence for it (times it was fine), the evidence against it (times it was not, and what the room does to urges), what the honest reason for going is, and an alternative that meets that reason. If the client still chooses to go, the sheet ends with a plan rather than a verdict. Watch for the client who treats this as a test they must pass by going; the sheet is about seeing the chain, not proving strength.', '[{"id": "f0", "type": "textarea", "label": "The permission thought, in the words my mind uses:"}, {"id": "f1", "type": "textarea", "label": "Times being there was fine, honestly:"}, {"id": "f2", "type": "textarea", "label": "Times it was not, and what the room did to my urges:"}, {"id": "f3", "type": "textarea", "label": "The real reason I want to go (the people, the game, the habit, the drink):"}, {"id": "f4", "type": "textarea", "label": "Another way to get that reason met tonight:"}, {"id": "f5", "type": "textarea", "label": "If I go anyway: my plan, my exit time, and the person I will text:"}]'::jsonb, array['addiction', 'permission thoughts', 'substance use']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('urge-as-a-telemarketer-call-i-let-go-to-voicemail-page', 'Urge as a Telemarketer Call I Let Go to Voicemail Page', 'act'::resource_kind, 'A defusion page that treats the urge as a telemarketer call: insistent, scripted and allowed to ring through to voicemail.', 'Use it to give the client a light way to let an urge call without picking up.', array['Adults']::text[], '15 minutes, then daily', 'Urges have scripts, like telemarketers: the same pitch, the same promise, a new number each time so the client picks up. The page asks the client to write the urge''s pitch word for word, notice how it tries to keep them on the line, and practice letting it ring through: the phone rings, they notice, they do not pick up, the ringing stops. The log tracks how long the ringing lasted when they did not answer. Watch for the client who argues with the telemarketer; arguing is still answering.', '[{"id": "f0", "type": "textarea", "label": "My urge''s pitch, written as the telemarketer would say it:"}, {"id": "f1", "type": "textarea", "label": "How it keeps me on the line when I pick up:"}, {"id": "f2", "type": "textarea", "label": "What letting it ring through looks like for me (a breath, a walk to another room, a sentence):"}, {"id": "f3", "type": "textarea", "label": "How long the ringing lasted when I did not answer, this week:"}, {"id": "f4", "type": "textarea", "label": "What I did with the minutes I was not on the line:"}]'::jsonb, array['addiction', 'urges', 'defusion']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('alternate-rebellion-instead-of-the-secret-drink-card', 'Alternate Rebellion Instead of the Secret Drink Card', 'dbt'::resource_kind, 'An alternate rebellion card for the client whose substance use is partly a private act of defiance.', 'Use it to honor the rebellious part with something that does not cost the client their morning.', array['Adults', 'Teens']::text[], '20 minutes to plan, then as needed', 'Some substance use is rebellion: against the rules, the family, the version of themselves everyone expects. Alternate rebellion asks the client to name what the use is rebelling against, what the rebellion feels like in the body, and then to invent rebellious acts that keep the feeling and lose the cost: the loud shirt, the unsent letter, the weeknight concert, the unpopular opinion said out loud. The log tracks which one they used and whether the urge settled. Watch for the client who picks a rebellion that harms someone else; the rule is that only the client''s own expectations get broken.', '[{"id": "f0", "type": "textarea", "label": "What my use is a rebellion against, honestly:"}, {"id": "f1", "type": "textarea", "label": "What the rebellion feels like in my body when it works:"}, {"id": "f2", "type": "textarea", "label": "Five rebellious acts that keep the feeling and skip the cost:"}, {"id": "f3", "type": "textarea", "label": "The one I used this week, and what the urge did afterward:"}, {"id": "f4", "type": "textarea", "label": "What the morning after an alternate rebellion was like compared with the other kind:"}]'::jsonb, array['addiction', 'alternate rebellion', 'urges']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('card-and-cash-access-in-early-recovery-pact-for-partners', 'Card and Cash Access in Early Recovery Pact for Partners', 'couples'::resource_kind, 'A couples agreement about cash, cards and account access in the early months of changing substance use, written by both partners.', 'Use it to make money boundaries a shared plan rather than one partner policing the other.', array['Couples']::text[], '30 minutes', 'Money is where substance use shows, and in early change couples often slide into one partner controlling every dollar and the other feeling like a child. The agreement asks the partner changing their use what access they want and what access they are asking to give up for now, and the other partner what they need to feel steady and what they will not do (snoop, interrogate). Together they set the arrangement, the review date, and how a slip in the money will be talked about. Watch for the agreement that has no end date; early recovery is a season, and the plan should say so.', '[{"id": "f0", "type": "textarea", "label": "Partner changing my use: what access I want, and what I am asking to give up for now:"}, {"id": "f1", "type": "textarea", "label": "Other partner: what I need to feel steady, and what I promise not to do:"}, {"id": "f2", "type": "textarea", "label": "Our arrangement for cash, cards and accounts, in plain terms:"}, {"id": "f3", "type": "textarea", "label": "How we will talk about a slip in the money without it becoming a trial:"}, {"id": "f4", "type": "textarea", "label": "Our review date, and what more access would look like:"}]'::jsonb, array['addiction', 'couples', 'money']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('snow-plow-blocking-the-driveway-again-anger-log-sheet', 'Snow Plow Blocking the Driveway Again Anger Log Sheet', 'worksheet'::resource_kind, 'An anger log for the repeated small injustice, the plowed-in driveway or its equivalent, tracked across a season.', 'Use it to find the pattern in a recurring anger instead of relitigating each instance.', array['Adults']::text[], 'Five minutes per episode', 'Some anger comes from a repeating event the client cannot control: the plow, the neighbor''s trash cans, the coworker''s reply-all. The log takes each episode: what happened, the intensity, the first thought, what the client did, how long it lasted, and what it cost them. After five entries, the review boxes ask what the pattern shows: whether the anger grows each time, what the fantasy response is, and what the one realistic action is (a call to the city, a shovel by the door, a letter). Watch for the client who logs the event in detail and their response in one word; the response is the data.', '[{"id": "f0", "type": "textarea", "label": "Each episode: what happened, intensity (0 to 10), my first thought, what I did, how long it lasted:"}, {"id": "f1", "type": "textarea", "label": "What the anger costs me each time (time, mood, the rest of the morning):"}, {"id": "f2", "type": "textarea", "label": "After five entries, what the pattern shows:"}, {"id": "f3", "type": "textarea", "label": "My fantasy response, written out and left here:"}, {"id": "f4", "type": "textarea", "label": "The one realistic action that might change the event or my morning:"}, {"id": "f5", "type": "textarea", "label": "What I will do the next time it happens, before the shovel:"}]'::jsonb, array['anger management', 'self-monitoring', 'triggers']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('they-cut-in-line-so-they-think-they-are-better-sheet', 'They Cut in Line So They Think They Are Better Sheet', 'cbt'::resource_kind, 'A mind reading sheet for the stranger who cuts in line and the story the client''s anger writes about them.', 'Use it to separate what a stranger did from what the client decided it meant.', array['Adults', 'Teens']::text[], '15 minutes', 'The line cutter is a reliable trigger because the client fills in a motive instantly: they think they are better, they saw me and did not care. The sheet asks for what actually happened, the motive the mind assigned, how sure the client is of it, three other explanations (distraction, a different line, a bad day), and what the anger did in the body under each story. The last box asks what the client would have wanted to do with the stranger if the motive had been the kindest one. Watch for the client who insists the motive was obvious; ask how they would know.', '[{"id": "f0", "type": "textarea", "label": "What the person actually did, with no motive attached:"}, {"id": "f1", "type": "textarea", "label": "The motive my mind assigned, and how sure I was (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "Three other explanations for the same behavior:"}, {"id": "f3", "type": "textarea", "label": "What my anger did in my body under my story, and under the kindest one:"}, {"id": "f4", "type": "textarea", "label": "What I would have done if I had assumed the kindest one:"}, {"id": "f5", "type": "textarea", "label": "Where else this week I assigned a motive to a stranger:"}]'::jsonb, array['anger management', 'mind reading', 'thinking traps']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('anger-as-a-dashboard-warning-light-page', 'Anger as a Dashboard Warning Light Page', 'act'::resource_kind, 'An acceptance page that reads anger as a dashboard light: it says something needs attention, not which pedal to press.', 'Use it to let the client treat anger as information rather than an instruction.', array['Adults', 'Teens']::text[], '20 minutes', 'A dashboard light is useful and ignorable in equal measure; it says look here, not drive faster. The page asks the client to list what their anger light tends to come on about, what it usually gets them to do (the pedal they press), what it might actually be pointing at (a boundary, tiredness, an unfairness that needs a different response), and what checking under the hood would look like instead of pressing anything. The last box is a value the anger is guarding. Watch for the client who wants the light disconnected; the page respects the light and questions the pedal.', '[{"id": "f0", "type": "textarea", "label": "What my anger light comes on about most often:"}, {"id": "f1", "type": "textarea", "label": "What it usually gets me to do:"}, {"id": "f2", "type": "textarea", "label": "What it might actually be pointing at:"}, {"id": "f3", "type": "textarea", "label": "What checking under the hood would look like, before I press anything:"}, {"id": "f4", "type": "textarea", "label": "The value my anger is guarding, in a few words:"}]'::jsonb, array['anger management', 'acceptance', 'values']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-the-sarcastic-reply-card', 'Opposite Action to the Sarcastic Reply Card', 'dbt'::resource_kind, 'An opposite action card for the moment anger wants to answer with sarcasm in a meeting, a text or a kitchen.', 'Use it to give the client a specific other move when sarcasm is the weapon of choice.', array['Adults', 'Teens']::text[], 'Five minutes, as needed', 'Sarcasm is anger''s polite disguise, and clients often do not count it as anger at all. The card asks the client to notice the urge to be clever at someone''s expense, check whether the anger fits the facts and whether acting on it works, and then do the opposite: a plain sentence that says what they mean, a softened face and voice, or gently stepping away. The log records the sarcastic line they did not say and the plain one they said instead. Watch for the client who turns the plain sentence into a weapon by tone; the opposite action includes the face and the voice.', '[{"id": "f0", "type": "textarea", "label": "The moment, and the sarcastic line I wanted to say:"}, {"id": "f1", "type": "textarea", "label": "Does my anger fit the facts, and would the sarcasm work for me?"}, {"id": "f2", "type": "textarea", "label": "The plain sentence I said instead, in the words I used:"}, {"id": "f3", "type": "textarea", "label": "What I did with my face and voice:"}, {"id": "f4", "type": "textarea", "label": "What happened next, compared with how the sarcasm usually lands:"}]'::jsonb, array['anger management', 'opposite action', 'communication']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('volcano-countdown-freeze-before-the-eruption-game', 'Volcano Countdown Freeze Before the Eruption Game', 'game'::resource_kind, 'A group game where players act out a volcano building pressure and must freeze on the leader''s call just before it erupts.', 'Use it to practice catching the pause before anger erupts, in a game loud enough to feel real.', array['Groups', 'Teens']::text[], '20 minutes', 'Rules: players stand in a circle and, on the leader''s count from one to ten, act out pressure building (rumbling, shaking, growing louder). The leader may call freeze at any number, and everyone must hold completely still, then take one slow breath together before the leader releases them. Turns: rotate the leader each round; the leader decides where the freeze lands. Debrief: freezing at eight versus at three, what the body did in the stillness, and each player''s real-life number where freezing is still possible. Ask the player who erupts for the laugh what the freeze would have cost.', '[{"id": "f0", "type": "textarea", "label": "What freezing felt like at a low number versus a high one:"}, {"id": "f1", "type": "textarea", "label": "What my body did in the freeze and the breath:"}, {"id": "f2", "type": "textarea", "label": "My real-life number: how far up the countdown I can still freeze:"}, {"id": "f3", "type": "textarea", "label": "What usually happens at the numbers above that:"}, {"id": "f4", "type": "textarea", "label": "One freeze move I could use this week when I feel the rumbling:"}]'::jsonb, array['anger management', 'group', 'regulation']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('locking-the-car-with-one-click-only-experiment-sheet', 'Locking the Car With One Click Only Experiment Sheet', 'worksheet'::resource_kind, 'A response prevention sheet for the car lock: one click, no walk back, no second press, and the discomfort logged.', 'Use it to give the client a contained daily experiment with the urge to check.', array['Adults', 'Teens']::text[], 'One week of daily parking', 'The car lock is a daily, bounded place to practice: one click of the fob and then walking away, with no return to tug the handle and no second press. The sheet asks for the current ritual (how many clicks, how many handle checks), the one-click rule, the distress at the moment of walking away and five minutes later, and what the mind said on the walk. A week of entries usually shows the curve. Watch for the client who replaces the second click with a glance back at the lights; name it as the same checking in a smaller coat and add it to the rule.', '[{"id": "f0", "type": "textarea", "label": "My current ritual at the car, honestly (clicks, handle tugs, looks back):"}, {"id": "f1", "type": "textarea", "label": "My rule for this week, in one line:"}, {"id": "f2", "type": "textarea", "label": "Each day: distress walking away (0 to 10), distress five minutes later, and what my mind said:"}, {"id": "f3", "type": "textarea", "label": "The sneaky substitutes I noticed (a glance back, a question to my passenger):"}, {"id": "f4", "type": "textarea", "label": "What the week''s numbers show:"}, {"id": "f5", "type": "textarea", "label": "What I will add to the rule next week:"}]'::jsonb, array['OCD', 'response prevention', 'checking']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('knocking-on-wood-prevents-harm-belief-check-sheet', 'Knocking on Wood Prevents Harm Belief Check Sheet', 'cbt'::resource_kind, 'A belief check for the small ritual, knocking on wood or its private cousin, that the client''s mind says keeps people safe.', 'Use it to examine the link between a tiny act and a feared outcome without demanding it stop today.', array['Adults', 'Teens']::text[], '20 minutes in session', 'Many clients have a private version of knocking on wood that they half believe and fully perform. The sheet names the ritual and the harm it is meant to prevent, asks how strongly the client believes the link when calm and when anxious, lists what the ritual costs, and sets up a small test: one day without it for a low-stakes thought, with the outcome and the distress recorded. Separate the belief from the relief; the ritual relieves, which is different from protecting. Watch for the client who tests it on the thought they fear most; start lower.', '[{"id": "f0", "type": "textarea", "label": "The ritual, and the harm it is supposed to prevent:"}, {"id": "f1", "type": "textarea", "label": "How strongly I believe the link when calm, and when anxious (0 to 100 each):"}, {"id": "f2", "type": "textarea", "label": "What the ritual costs me in a day:"}, {"id": "f3", "type": "textarea", "label": "How the relief works, separately from whether it protects anyone:"}, {"id": "f4", "type": "textarea", "label": "One low-stakes thought I will leave unknocked this week, and what happened:"}, {"id": "f5", "type": "textarea", "label": "The belief rated again, calm and anxious:"}]'::jsonb, array['OCD', 'magical thinking', 'behavioral experiment']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('doubt-as-a-spam-caller-with-a-new-number-each-time-page', 'Doubt as a Spam Caller With a New Number Each Time Page', 'act'::resource_kind, 'A defusion page for the doubting mind that keeps calling from a new number so the client picks up every time.', 'Use it to help the client recognize the caller by the pitch, not the number.', array['Adults', 'Teens']::text[], '15 minutes, then daily', 'Obsessional doubt is clever about disguise: did I lock it, did I mean that, is this the one that is real. The page asks the client to list this week''s calls (the new numbers), then to find the pitch they all share, which is the tell. The practice is to notice the pitch within the first sentence and let the call ring out, logging how many rings. The page does not ask whether any particular call was real; that is answering it. Watch for the client who wants to check the number one more time to be sure it is spam; that is the whole loop in miniature.', '[{"id": "f0", "type": "textarea", "label": "This week''s doubt calls, each from its new number:"}, {"id": "f1", "type": "textarea", "label": "The pitch they all share, the tell that it is the same caller:"}, {"id": "f2", "type": "textarea", "label": "How soon into the call I recognized the pitch:"}, {"id": "f3", "type": "textarea", "label": "How many rings until it stopped when I did not answer:"}, {"id": "f4", "type": "textarea", "label": "What I did with the minutes I did not spend on the call:"}]'::jsonb, array['OCD', 'defusion', 'intrusive thoughts']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('observe-the-not-quite-even-shoelaces-without-fixing-card', 'Observe the Not Quite Even Shoelaces Without Fixing Card', 'dbt'::resource_kind, 'A mindfulness card for the small asymmetry, uneven laces or a slightly off collar, observed for one minute and left alone.', 'Use it to let the client sit with not quite right in a place that cannot do harm.', array['Adults', 'Teens']::text[], 'One minute, daily', 'The not-right feeling attaches to small things, and shoelaces are a safe place to practice sitting with it. The card asks the client to tie their shoes unevenly on purpose, observe the feeling without words for one minute (where it lives, how it moves), then describe it in plain language and walk out the door without fixing it. The log records the distress at the door and at the end of the first hour. Watch for the client who fixes the laces at the first stop; note it without judgment and shorten the goal to the end of the driveway.', '[{"id": "f0", "type": "textarea", "label": "Observe: where the not-right feeling lives, and how it moves over one minute:"}, {"id": "f1", "type": "textarea", "label": "Describe: the feeling in plain words, no story:"}, {"id": "f2", "type": "textarea", "label": "Distress at the door (0 to 10), and at the end of the first hour:"}, {"id": "f3", "type": "textarea", "label": "Whether I fixed them, and when:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the feeling by the end of the day:"}]'::jsonb, array['OCD', 'mindfulness', 'just right']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('bossy-thought-traffic-cone-stop-sign-craft', 'Bossy Thought Traffic Cone Stop Sign Craft', 'kids'::resource_kind, 'A kids craft: a paper traffic cone the child holds up to the bossy thought that keeps telling them to check, count or redo.', 'Use it to give a child a playful way to stop and not obey a sticky, bossy thought.', array['Children']::text[], '25 minutes', 'The child makes a traffic cone from orange paper (a rolled cone with white stripes) and decorates it as the stop sign for their bossy thought, which they name. When the bossy thought says check again or do it over, the child holds up the cone and says the cone''s line (not right now, bossy thought). The parent practices with the child by playing the bossy thought in a silly voice and letting the cone win. In session, ask what the bossy thought does when the cone comes out. Watch for the parent who uses the cone to rush the child through a hard moment; the cone is the child''s to hold up.', '[{"id": "f0", "type": "textarea", "label": "Decorate your traffic cone and write the bossy thought''s name on it:"}, {"id": "f1", "type": "textarea", "label": "What the bossy thought tells me to do most:"}, {"id": "f2", "type": "textarea", "label": "The cone''s line, in my own words:"}, {"id": "f3", "type": "textarea", "label": "What the bossy thought did when I held up the cone:"}, {"id": "f4", "type": "textarea", "label": "Parent: a time this week I saw my child use the cone, and what I said:"}]'::jsonb, array['OCD', 'children', 'craft']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('breathing-through-a-coffee-stirrer-air-hunger-log-sheet', 'Breathing Through a Coffee Stirrer Air Hunger Log Sheet', 'worksheet'::resource_kind, 'An interoceptive practice log: a minute of breathing through a narrow coffee stirrer, bringing on air hunger and logging what happens.', 'Use it to let the client meet the breathless feeling on purpose and watch it fade.', array['Adults', 'Teens']::text[], 'Ten minutes daily for a week', 'Air hunger is often the sensation a panic-prone client fears most, and a coffee stirrer brings it on safely in one minute. The log records the prediction before each round, the peak intensity, how long it took to settle after the stirrer came out, and what the mind said during. Start in session with you timing and talking the client through it, and only then assign it at home. Clients with asthma or a breathing condition should check with their physician first, and the sheet says so. Watch for the client who takes the stirrer out at the first flicker; agree on the time before starting.', '[{"id": "f0", "type": "textarea", "label": "Before the round: what I predict will happen, and how bad it will get (0 to 10):"}, {"id": "f1", "type": "textarea", "label": "Peak intensity, and what the sensation actually was:"}, {"id": "f2", "type": "textarea", "label": "How many seconds it took to settle after I stopped:"}, {"id": "f3", "type": "textarea", "label": "What my mind said during the minute:"}, {"id": "f4", "type": "textarea", "label": "After a week, what the numbers show about the sensation and my prediction:"}, {"id": "f5", "type": "textarea", "label": "Where this sensation showed up in daily life this week, and what I did:"}]'::jsonb, array['panic attacks', 'interoceptive exposure', 'self-monitoring']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('needing-to-sit-down-means-i-am-losing-control-check-sheet', 'Needing to Sit Down Means I Am Losing Control Check Sheet', 'cbt'::resource_kind, 'A check sheet for the thought that having to sit down during a surge means the client is about to lose control.', 'Use it to separate a wise body move from the catastrophe the client reads into it.', array['Adults', 'Teens']::text[], '15 minutes', 'Sitting down during a surge is a sensible move the client often experiences as proof of collapse. The sheet asks what losing control would actually look like, how many times the client has sat down during a surge and what happened next, what sitting down accomplished (a pulse that settled, a moment to breathe), and the probability the client now assigns to the feared outcome. The balanced thought is one the client can think while lowering into the chair. Watch for the client who avoids sitting to prove they are fine; that is the belief running the show.', '[{"id": "f0", "type": "textarea", "label": "What losing control would actually look like, specifically:"}, {"id": "f1", "type": "textarea", "label": "How many times I have sat down during a surge, and what happened next each time:"}, {"id": "f2", "type": "textarea", "label": "What sitting down accomplished for my body:"}, {"id": "f3", "type": "textarea", "label": "The probability I give the feared outcome now (0 to 100):"}, {"id": "f4", "type": "textarea", "label": "A sentence I can think while lowering into the chair:"}, {"id": "f5", "type": "textarea", "label": "What I will let myself do the next time the surge comes in public:"}]'::jsonb, array['panic attacks', 'catastrophizing', 'safety behaviors']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('panic-as-a-pop-up-thunderstorm-page', 'Panic as a Pop-Up Thunderstorm Page', 'act'::resource_kind, 'An acceptance page that frames a panic surge as a pop-up thunderstorm: sudden, loud, drenching and over in minutes.', 'Use it to help the client stop running for cover and let the storm pass through them.', array['Adults', 'Teens']::text[], '15 minutes', 'A pop-up thunderstorm arrives from a clear sky, soaks everything, and is gone before the ground dries. The page asks the client to describe their surges as a storm (the first dark cloud, the downpour, the length), what running for cover has looked like (leaving, calling, bracing), and what standing in the rain would look like instead: feet planted, breath slow, hands open, the storm allowed. The practice is one sentence to say when the cloud appears. Watch for the client who hears standing in the rain as doing nothing; it is a posture, and posture is a lot.', '[{"id": "f0", "type": "textarea", "label": "My surges described as a storm: the first cloud, the downpour, how long until it passes:"}, {"id": "f1", "type": "textarea", "label": "What running for cover has looked like for me:"}, {"id": "f2", "type": "textarea", "label": "What standing in the rain would look like: body, breath, hands:"}, {"id": "f3", "type": "textarea", "label": "My sentence for the first dark cloud:"}, {"id": "f4", "type": "textarea", "label": "What I noticed the last time I let one pass through instead of running:"}]'::jsonb, array['panic attacks', 'acceptance', 'metaphor']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('paced-breathing-in-the-dentists-waiting-room-card', 'Paced Breathing in the Dentist''s Waiting Room Card', 'dbt'::resource_kind, 'A paced breathing card for the dentist''s waiting room, where the chair, the sounds and the wait stack up.', 'Use it to give the client a slow breath pattern tied to a room they already dread.', array['Adults', 'Teens']::text[], 'Five minutes in the waiting room', 'The dental waiting room is a place where panic-prone clients arrive already breathing fast. The card sets a paced pattern (in for four, out for six or longer, the exhale always longer), gives the client something to count with (the tiles, the magazines, the fish tank), and asks them to log their pulse or distress before and after five minutes. A line for what to say to the hygienist about needing a moment is included. Rehearse the pattern in session until the count is automatic. Watch for the client who breathes faster trying to do it right; the exhale is the whole skill.', '[{"id": "f0", "type": "textarea", "label": "My count: in for __, out for __ (the exhale longer):"}, {"id": "f1", "type": "textarea", "label": "What in the room I will count with:"}, {"id": "f2", "type": "textarea", "label": "Distress or pulse before five minutes, and after:"}, {"id": "f3", "type": "textarea", "label": "What I will say if I am called before I am ready:"}, {"id": "f4", "type": "textarea", "label": "How the chair felt compared with the last visit:"}]'::jsonb, array['panic attacks', 'paced breathing', 'health']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('hot-face-sensation-scarf-wrap-guessing-game', 'Hot Face Sensation Scarf Wrap Guessing Game', 'game'::resource_kind, 'A group game where players wrap a scarf snugly around the face and neck for a minute, feel the heat rise, and guess what the sensation is.', 'Use it to let a group meet a feared sensation together and discover it is just heat.', array['Groups', 'Teens']::text[], '20 minutes', 'Rules: each player wraps a scarf around the lower face and neck for sixty seconds while walking in place, then removes it and describes the sensation in three words before anyone says the word panic. Others guess what the player felt. Turns: go around twice; the second round, players predict their rating before wrapping. Debrief: how close the predictions were, how long the heat took to fade, who found it funny and who found it hard, and where in life this heat shows up uninvited. Anyone may sit out any round; the player who rips the scarf off early gets ten seconds next time.', '[{"id": "f0", "type": "textarea", "label": "My three words for the sensation:"}, {"id": "f1", "type": "textarea", "label": "My prediction in round two, and what actually happened:"}, {"id": "f2", "type": "textarea", "label": "How long the heat took to fade:"}, {"id": "f3", "type": "textarea", "label": "What I noticed about doing a hard sensation in a room full of people:"}, {"id": "f4", "type": "textarea", "label": "Where this heat shows up uninvited in my life, and what I usually do:"}]'::jsonb, array['panic attacks', 'group', 'interoceptive exposure']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('screen-time-limits-for-the-school-break-week-sheet', 'Screen Time Limits for the School Break Week Sheet', 'worksheet'::resource_kind, 'A planning sheet for the week off school: the screen limits, the alternatives and the parent''s own plan for the pushback.', 'Use it to set the break''s screen rules before the first argument instead of during it.', array['Adults']::text[], '20 minutes before the break', 'The school break collapses every screen rule in a day unless the parent decides ahead. The sheet asks for the weekday rule and the break rule (they can differ), when screens are on and off, three things that are available instead and ready to go, the parent''s line for the fiftieth request, and what the parent will do with their own phone in front of the kids. The debrief after the break asks what held and what did not. Watch for the parent who sets the limit at a number they already know they cannot hold; agree on the honest number.', '[{"id": "f0", "type": "textarea", "label": "Our normal screen rule, and the break week rule:"}, {"id": "f1", "type": "textarea", "label": "When screens are on and when they are off each day:"}, {"id": "f2", "type": "textarea", "label": "Three things ready to go instead, with what they need set up:"}, {"id": "f3", "type": "textarea", "label": "My line for the fiftieth request, said the same way every time:"}, {"id": "f4", "type": "textarea", "label": "What I will do with my own phone in front of the kids this week:"}, {"id": "f5", "type": "textarea", "label": "After the break: what held, what did not, and what I would change:"}]'::jsonb, array['parenting', 'routines', 'planning']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('if-my-kid-is-bored-i-am-failing-them-thought-record', 'If My Kid Is Bored I Am Failing Them Thought Record', 'cbt'::resource_kind, 'A thought record for the parent who hears a child''s boredom as a verdict on their parenting.', 'Use it to separate a child''s ordinary boredom from the parent''s story of failing.', array['Adults']::text[], '20 minutes', 'A bored child is a normal event that an anxious parent turns into an indictment. The record takes the moment (the whine, the I am bored), the hot thought, the emotion and its intensity, the evidence for and against the thought, and the thinking traps (should statements, personalization, mind reading the other parents). The balanced thought is one the parent can hold while not entertaining the child. A box for what boredom can give a child is included. Watch for the parent who fills every gap to avoid the thought; the action step is letting one gap stand.', '[{"id": "f0", "type": "textarea", "label": "The moment my child said they were bored, and what I did:"}, {"id": "f1", "type": "textarea", "label": "The hot thought, and the emotion with its intensity (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "Evidence that boredom means I am failing them:"}, {"id": "f3", "type": "textarea", "label": "Evidence against it, including what boredom has given me and them:"}, {"id": "f4", "type": "textarea", "label": "The thinking traps I can spot:"}, {"id": "f5", "type": "textarea", "label": "A balanced thought, and one gap I will let stand this week:"}]'::jsonb, array['parenting', 'thought record', 'personalization']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('values-when-the-report-card-comes-home-page', 'Values When the Report Card Comes Home Page', 'act'::resource_kind, 'A values page for the evening the report card arrives and the parent''s reaction decides the conversation.', 'Use it to let the parent meet the grades as the parent they mean to be.', array['Adults']::text[], '15 minutes before opening it', 'The report card arrives and the parent''s mind fills with its own school years, comparisons, and fear for the future, all in the ten seconds before speaking. The page asks what the parent''s mind is likely to say, what kind of parent they want to be in that conversation (curious, steady, on the child''s side), what the child most needs to hear first, and the one question they will ask instead of the one their mind suggests. The debrief asks what the conversation was like with the value chosen ahead. Silence is also a reaction, and the child reads it.', '[{"id": "f0", "type": "textarea", "label": "What my mind is likely to say in the first ten seconds:"}, {"id": "f1", "type": "textarea", "label": "The kind of parent I want to be in that conversation:"}, {"id": "f2", "type": "textarea", "label": "What my child most needs to hear first, whatever the grades say:"}, {"id": "f3", "type": "textarea", "label": "The one question I will ask instead of the one my mind suggests:"}, {"id": "f4", "type": "textarea", "label": "What the conversation was like with the value chosen ahead:"}]'::jsonb, array['parenting', 'values', 'communication']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('give-skills-with-the-teen-who-slams-the-door-card', 'GIVE Skills With the Teen Who Slams the Door Card', 'dbt'::resource_kind, 'A GIVE card for the minutes after a teenager''s slammed door, when the parent wants to follow with a lecture.', 'Use it to keep the relationship when the parent''s urge is to win the moment.', array['Adults']::text[], 'Ten minutes after the slam', 'A slammed door invites a parent to open it and win. GIVE asks for something harder: a Gentle approach (no threats, no following through the door), Interest in what set it off, Validation of the feeling even while the slam stays off limits, and an Easy manner that leaves room for the teen to come back. The card asks the parent to write what they would have said at the door and what they will say instead, when (after a cooling period), and how they will raise the slam itself later. Watch for the parent who hears validation as approving the slam; the card separates the feeling from the door.', '[{"id": "f0", "type": "textarea", "label": "What I wanted to say through the door, word for word:"}, {"id": "f1", "type": "textarea", "label": "Gentle: how I will approach when I do (timing, tone, where I stand):"}, {"id": "f2", "type": "textarea", "label": "Interest: the question I will ask about what set it off:"}, {"id": "f3", "type": "textarea", "label": "Validation: the sentence that names the feeling without approving the slam:"}, {"id": "f4", "type": "textarea", "label": "Easy manner: how I will leave room for my teen to come back:"}, {"id": "f5", "type": "textarea", "label": "How and when I will raise the slam itself:"}]'::jsonb, array['parenting', 'GIVE', 'interpersonal effectiveness']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('family-weather-report-mood-check-in-board-craft', 'Family Weather Report Mood Check-In Board Craft', 'kids'::resource_kind, 'A kids craft: a family weather board where each person moves their marker to the sky that matches their mood at dinner.', 'Use it to give a family a shared, low-pressure way to say how the day went.', array['Children']::text[], '30 minutes to make, then a minute at dinner', 'The child makes a board with four or five skies (sunny, cloudy, rainy, stormy, rainbow) and a marker for each family member, clipped on with clothespins. At dinner, everyone moves their marker and may say one sentence about the weather or nothing at all. The parent goes first and includes a stormy day sometimes, so the board is for everyone, not a check on the child. In session, ask the child what the family''s weather has been this week. Watch for the parent who asks why about a rainy marker at the table; the board is for naming, and the why can wait for bedtime.', '[{"id": "f0", "type": "textarea", "label": "Draw your weather board and the skies on it:"}, {"id": "f1", "type": "textarea", "label": "Our family''s weather this week, who was where:"}, {"id": "f2", "type": "textarea", "label": "A day my weather changed between morning and dinner:"}, {"id": "f3", "type": "textarea", "label": "Parent: what I said about my own stormy or rainy marker:"}, {"id": "f4", "type": "textarea", "label": "Parent: what the board changed about dinner talk:"}]'::jsonb, array['parenting', 'children', 'emotion identification']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('phone-reminders-for-my-own-meals-and-water-sheet', 'Phone Reminders for My Own Meals and Water Sheet', 'worksheet'::resource_kind, 'A self-care setup sheet for the new parent who feeds the baby on schedule and forgets to feed themselves.', 'Use it to put the parent''s own meals and water on the same reminder system the baby already has.', array['Adults']::text[], '15 minutes to set up, then one week', 'New parents track every feed and diaper and skip their own lunch for days. The sheet asks the client to notice when they last ate and drank today, choose three reminder times that sit next to the baby''s feeds, list five foods that can be eaten one-handed and need no cooking, decide where the water bottle lives, and log the week. It is a logistics tool, not a nutrition plan, and it does not ask about amounts. Watch for the client who feels silly setting reminders for eating; name that the baby''s reminders are the same thing.', '[{"id": "f0", "type": "textarea", "label": "When I last ate and drank today, honestly:"}, {"id": "f1", "type": "textarea", "label": "Three reminder times that sit next to the baby''s feeds:"}, {"id": "f2", "type": "textarea", "label": "Five one-handed foods that need no cooking, and who can stock them:"}, {"id": "f3", "type": "textarea", "label": "Where the water bottle lives, and who refills it:"}, {"id": "f4", "type": "textarea", "label": "This week''s log: reminders I answered, and what got in the way of the ones I did not:"}, {"id": "f5", "type": "textarea", "label": "How my afternoons felt on the days I ate:"}]'::jsonb, array['perinatal and postpartum', 'self-care', 'routines']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('if-i-am-not-glowing-something-is-wrong-with-me-sheet', 'If I Am Not Glowing Something Is Wrong With Me Sheet', 'cbt'::resource_kind, 'A thought sheet for the new or expecting parent who measures themselves against the glowing version everyone promised.', 'Use it to loosen the gap between the advertised experience and the real one.', array['Adults']::text[], '20 minutes', 'The glow is a story told to every expecting and new parent, and its absence becomes evidence of a personal flaw. The sheet names the thought, where the glow story came from (ads, relatives, posts), the evidence against the idea that everyone else glows, the thinking traps (all-or-nothing, mental filter, comparison), and a balanced thought the client can say when a stranger asks if they are loving every minute. A client whose low mood is persistent or frightening needs a conversation with you and their physician. The sheet is for the honest answer, guilt and all.', '[{"id": "f0", "type": "textarea", "label": "The thought in my words, and when it hits hardest:"}, {"id": "f1", "type": "textarea", "label": "Where the glow story came from, specifically:"}, {"id": "f2", "type": "textarea", "label": "What I actually feel on an ordinary day, in plain words:"}, {"id": "f3", "type": "textarea", "label": "Evidence that not glowing is common, from people I actually know:"}, {"id": "f4", "type": "textarea", "label": "The thinking traps I can spot:"}, {"id": "f5", "type": "textarea", "label": "What I will say when someone asks if I am loving every minute:"}]'::jsonb, array['perinatal and postpartum', 'thinking traps', 'comparison']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('postpartum-body-as-a-house-mid-renovation-page', 'Postpartum Body as a House Mid-Renovation Page', 'act'::resource_kind, 'An acceptance page for the postpartum body as a house in the middle of a renovation: unfinished, in use, and still home.', 'Use it to help the client live in the body they have today without waiting for the finished version.', array['Adults']::text[], '15 minutes', 'The postpartum body is often treated as a problem to fix back, and the waiting takes months out of a life. The page offers a house mid-renovation: dust, exposed beams, a kitchen that works anyway, people living in it the whole time. The client describes what their mind says about the house, what the house is doing right now (feeding, carrying, sleeping in shifts), what the mind postpones until the renovation is done, and one thing they will do in the house this week as it is. It never mentions size or food; it is about living there. Watch for the client who makes the renovation a deadline.', '[{"id": "f0", "type": "textarea", "label": "What my mind says about the house right now:"}, {"id": "f1", "type": "textarea", "label": "What the house is actually doing today:"}, {"id": "f2", "type": "textarea", "label": "What I have been postponing until the renovation is done:"}, {"id": "f3", "type": "textarea", "label": "One thing I will do in the house this week, as it is:"}, {"id": "f4", "type": "textarea", "label": "What I would say to a friend living in a house mid-renovation:"}]'::jsonb, array['perinatal and postpartum', 'acceptance', 'body image']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('check-the-facts-on-the-babys-grunting-in-the-crib-card', 'Check the Facts on the Baby''s Grunting in the Crib Card', 'dbt'::resource_kind, 'A check the facts card for the 2 a.m. noises from the crib that the parent''s mind turns into an emergency.', 'Use it to let the parent sort a normal night sound from a call to act, before the surge takes over.', array['Adults']::text[], 'Three minutes at night', 'Night noises from a baby are many and strange, and a tired parent''s emotion mind hears each one as danger. The card asks what the sound was, what the mind said it meant, what the parent actually observed (breathing, color, movement, a settled baby a minute later), and whether the emotion fits the facts. It also asks what the pediatrician said counts as a reason to call, so the card never talks a parent out of a real one. Watch for the parent who checks the facts and then checks the baby twenty more times; the card is for the surge, not a replacement for the monitor.', '[{"id": "f0", "type": "textarea", "label": "The sound, and what my mind said it meant:"}, {"id": "f1", "type": "textarea", "label": "What I actually observed in the first minute:"}, {"id": "f2", "type": "textarea", "label": "What the pediatrician told me counts as a reason to call, written here so I do not have to remember at 2 a.m.:"}, {"id": "f3", "type": "textarea", "label": "Does my fear fit the facts tonight, and how intense is it (0 to 10)?"}, {"id": "f4", "type": "textarea", "label": "What I will do now (settle back, watch one minute, call), and how I will get back to sleep:"}]'::jsonb, array['perinatal and postpartum', 'check the facts', 'sleep']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('night-out-without-the-baby-first-date-plan-for-new-parents', 'Night Out Without the Baby First Date Plan for New Parents', 'couples'::resource_kind, 'A couples plan for the first evening out without the baby, covering the sitter, the phone, the guilt and what to talk about.', 'Use it to let a couple have two hours as partners without the evening becoming a test of either one.', array['Couples']::text[], '20 minutes a week ahead', 'The first night out after a baby is loaded: one partner may be counting the minutes until they can check in, the other hoping for one conversation that is not about the baby. The plan asks each partner what they want from the evening and what they dread, agrees how often the phone gets checked and who checks it, sets a bail-out rule neither will be shamed for, and lists three things to talk about that are not the baby (with permission to fail and talk about the baby anyway). Watch for the partner who agrees to go and plans to be miserable; invite them to name what would make it worth it.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I want from the evening, and what I dread:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I want from the evening, and what I dread:"}, {"id": "f2", "type": "textarea", "label": "Our phone rule: how often, who checks, and what counts as a reason to call home:"}, {"id": "f3", "type": "textarea", "label": "Our bail-out rule, with no shame attached:"}, {"id": "f4", "type": "textarea", "label": "Three things to talk about that are not the baby (and permission to talk about the baby anyway):"}, {"id": "f5", "type": "textarea", "label": "How we will handle the guilt on the drive there:"}]'::jsonb, array['perinatal and postpartum', 'couples', 'connection']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('jobs-i-have-been-trusted-with-timeline-sheet', 'Jobs I Have Been Trusted With Timeline Sheet', 'worksheet'::resource_kind, 'A timeline of the responsibilities other people have handed the client over the years, from babysitting to keys to a budget.', 'Use it to give a client who feels unreliable a record of being trusted that they did not write themselves.', array['Adults', 'Teens']::text[], '25 minutes', 'Clients with low self-worth discount their own account of themselves, so this sheet borrows other people''s. It asks for every job, errand or responsibility someone else chose to hand them (a sibling to watch, a spare key, a class pet, a shift to cover, a secret), who handed it over, and what that person must have believed to do it. The last boxes ask what the pattern across the timeline says and what the client''s mind does with the evidence. Watch for the client who adds a failure to every entry; keep the sheet to what was handed over, not how it went.', '[{"id": "f0", "type": "textarea", "label": "Childhood: what I was trusted with, and by whom:"}, {"id": "f1", "type": "textarea", "label": "Teen years: what I was trusted with, and by whom:"}, {"id": "f2", "type": "textarea", "label": "Adult life: what I have been trusted with, and by whom:"}, {"id": "f3", "type": "textarea", "label": "For three entries, what the person must have believed about me to hand it over:"}, {"id": "f4", "type": "textarea", "label": "What the pattern across the timeline says:"}, {"id": "f5", "type": "textarea", "label": "What my mind does with this evidence, and what I want to do with it:"}]'::jsonb, array['self-esteem', 'evidence', 'strengths']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('being-average-means-being-worthless-continuum-sheet', 'Being Average Means Being Worthless Continuum Sheet', 'cbt'::resource_kind, 'A continuum sheet for the all-or-nothing belief that anything short of exceptional makes the client worthless.', 'Use it to put the client on a scale with real people instead of at one of two poles.', array['Adults', 'Teens']::text[], '25 minutes', 'The belief hides in two poles: exceptional or worthless, with nothing between. The sheet draws a line from zero to one hundred, asks the client to define each end in behavior rather than labels, place five real people they know along it, place themselves, and then notice where most people they respect land. The last box asks what average would have to mean for the belief to be true, and whether the client believes that about anyone else. Watch for the client who places everyone they like above ninety; ask them to describe what a seventy looks like and who they know there.', '[{"id": "f0", "type": "textarea", "label": "What a zero looks like, in behavior, and what a hundred looks like:"}, {"id": "f1", "type": "textarea", "label": "Five real people I know, placed on the line with their numbers:"}, {"id": "f2", "type": "textarea", "label": "Where I place myself, and why:"}, {"id": "f3", "type": "textarea", "label": "Where most people I respect land:"}, {"id": "f4", "type": "textarea", "label": "What average would have to mean for my belief to be true:"}, {"id": "f5", "type": "textarea", "label": "Whether I believe that about anyone else on the line, and what that tells me:"}]'::jsonb, array['self-esteem', 'continuum', 'all-or-nothing']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('self-worth-as-the-riverbed-not-the-water-level-page', 'Self-Worth as the Riverbed Not the Water Level Page', 'act'::resource_kind, 'A self-as-context page for worth as the riverbed, which holds the river whether the water runs high or low.', 'Use it to give the client a sense of self that does not rise and fall with the week''s results.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients often locate worth in the water level: a good week and they are full, a bad one and they are dry. The page offers the riverbed: the shape that holds every level, carved over years, unchanged by a dry week. The client describes what raises and lowers their water, what they tell themselves at low water, what the riverbed has held over time (every level, every season), and one thing they could do this week from the riverbed rather than the level. Watch for the client who hears the riverbed as an excuse not to care about the water; the bed still cares which way the river runs.', '[{"id": "f0", "type": "textarea", "label": "What raises my water level, and what lowers it:"}, {"id": "f1", "type": "textarea", "label": "What I tell myself at low water:"}, {"id": "f2", "type": "textarea", "label": "What my riverbed has held over the years, every level and season:"}, {"id": "f3", "type": "textarea", "label": "How the riverbed is different from the water, in my own words:"}, {"id": "f4", "type": "textarea", "label": "One thing I will do this week from the riverbed, whatever the level:"}]'::jsonb, array['self-esteem', 'self-as-context', 'metaphor']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('build-mastery-by-sewing-the-loose-button-card', 'Build Mastery by Sewing the Loose Button Card', 'dbt'::resource_kind, 'A build mastery card for one small repair the client has put off, a loose button or a fallen hem, done this week.', 'Use it to give the client a finished, visible competence in under half an hour.', array['Adults', 'Teens']::text[], '30 minutes once this week', 'A loose button is a small, visible job the client has walked past for weeks, and finishing it is a clean hit of mastery. The card asks for the garment, what is needed (needle, thread, a video if the client has never done it), the day and hour, the predicted difficulty, and what the client''s mind says about needing a card for a button. The log records how it went and what wearing the repaired thing was like. For a client who already sews, pick the repair they have avoided instead. Watch for the client who buys a new shirt instead; that is the avoidance to name, kindly.', '[{"id": "f0", "type": "textarea", "label": "The garment, and how long it has been waiting:"}, {"id": "f1", "type": "textarea", "label": "What I need, and whether I need to watch someone do it first:"}, {"id": "f2", "type": "textarea", "label": "The day and hour, and my predicted difficulty (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "What my mind says about needing a card for a button:"}, {"id": "f4", "type": "textarea", "label": "How it went, and what wearing the repaired thing was like:"}]'::jsonb, array['self-esteem', 'build mastery', 'skills']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('strengths-auction-bid-on-a-quality-game', 'Strengths Auction Bid on a Quality Game', 'game'::resource_kind, 'A group game where players bid play money on the strengths they most want, then discover which ones others already see in them.', 'Use it to let a group talk about qualities out loud and hear what others see.', array['Groups', 'Teens']::text[], '30 minutes', 'Rules: each player gets a hundred units of play money. The leader auctions strengths one at a time (patience, humor, courage, loyalty) and players bid on the ones they most want more of. After the auction, each player names one strength they already see in the person to their left. Turns: the auctioneer rotates every five strengths. Debrief: which strengths were fought over, which went unbid, and what it was like to be told you already have what you were trying to buy. Ask the player who bids everything on one strength what it means to them.', '[{"id": "f0", "type": "textarea", "label": "The strengths I bid on, and how much I spent:"}, {"id": "f1", "type": "textarea", "label": "The strength I wanted most, and why:"}, {"id": "f2", "type": "textarea", "label": "The strength someone said they already see in me:"}, {"id": "f3", "type": "textarea", "label": "What it was like to hear that, in a few words:"}, {"id": "f4", "type": "textarea", "label": "A strength that went unbid that I think I have:"}]'::jsonb, array['self-esteem', 'group', 'strengths']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('saying-hello-to-the-neighbor-i-have-avoided-steps-sheet', 'Saying Hello to the Neighbor I Have Avoided Steps Sheet', 'worksheet'::resource_kind, 'A graded steps sheet for the neighbor the client has dodged for months, from a wave to a sentence to a name.', 'Use it to turn a daily avoidance into a short ladder the client can climb on their own street.', array['Adults', 'Teens']::text[], 'Two weeks of small steps', 'The avoided neighbor is a daily event: the client times their exits to miss them, and the avoidance grows a story about what the neighbor must think. The sheet asks for the current avoidance, the story, and then a ladder: eye contact and a nod, a wave, a hello, a sentence about the weather, asking their name. Each step is logged with the predicted and actual awkwardness. The last box asks what the neighbor actually did. Watch for the client who plans the first step for the day the neighbor is away; the ladder needs the neighbor.', '[{"id": "f0", "type": "textarea", "label": "How I currently avoid them, and the story I have built about what they think:"}, {"id": "f1", "type": "textarea", "label": "My ladder, from a nod to a name, with predicted awkwardness for each (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "Step one: when I did it, actual awkwardness, and what they did:"}, {"id": "f3", "type": "textarea", "label": "Steps two and three, logged the same way:"}, {"id": "f4", "type": "textarea", "label": "What the neighbor actually did, compared with my story:"}, {"id": "f5", "type": "textarea", "label": "What I will do the next time I see them:"}]'::jsonb, array['social anxiety', 'exposure', 'hierarchy']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('blushing-means-everyone-can-see-i-am-anxious-sheet', 'Blushing Means Everyone Can See I Am Anxious Sheet', 'cbt'::resource_kind, 'A thought sheet for the blush, the belief that it is visible from across the room and that it announces the client''s anxiety.', 'Use it to test what a blush actually shows, and what others actually make of it.', array['Adults', 'Teens']::text[], '20 minutes', 'The blush feels like a billboard. The sheet asks what the client believes others see and conclude, how sure they are, what they themselves conclude when someone else blushes, and a small experiment: ask one trusted person, after a conversation where the client felt the blush, whether they noticed and what they thought. A box for how long the blush actually lasts (timed, not felt) is included. Watch for the client who checks the mirror after; that is a safety behavior worth adding to the list.', '[{"id": "f0", "type": "textarea", "label": "What I believe people see when I blush, and what they conclude:"}, {"id": "f1", "type": "textarea", "label": "How sure I am (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "What I conclude when I see someone else blush:"}, {"id": "f3", "type": "textarea", "label": "How long a blush actually lasts when I time it, versus how long it feels:"}, {"id": "f4", "type": "textarea", "label": "The trusted person I asked, and what they said:"}, {"id": "f5", "type": "textarea", "label": "The belief rated again, and what I will stop doing to check:"}]'::jsonb, array['social anxiety', 'thinking traps', 'behavioral experiment']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('social-mind-as-a-subtitles-track-nobody-else-can-read-page', 'Social Mind as a Subtitles Track Nobody Else Can Read Page', 'act'::resource_kind, 'A defusion page that frames the anxious running commentary as a subtitles track playing only on the client''s screen.', 'Use it to help the client notice the subtitles without reading them aloud to the room.', array['Adults', 'Teens']::text[], '15 minutes, then in the next conversation', 'In a conversation, the anxious mind runs subtitles under every line: that was stupid, they are bored, say something. The page asks the client to write the subtitles from a recent conversation, then to notice that no one else could read them, and to practice letting the track run while watching the actual scene (the person''s face, their words). The log asks what they noticed about the other person when they were not reading the subtitles. Watch for the client who tries to turn the subtitles off; the practice is reading less, not switching off.', '[{"id": "f0", "type": "textarea", "label": "The subtitles from a recent conversation, written as they ran:"}, {"id": "f1", "type": "textarea", "label": "What the other person actually said and did, as far as I noticed:"}, {"id": "f2", "type": "textarea", "label": "What I missed in the scene while reading the subtitles:"}, {"id": "f3", "type": "textarea", "label": "My move for letting the track run while watching the scene:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the other person in the next conversation:"}]'::jsonb, array['social anxiety', 'defusion', 'metaphor']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('fast-skill-declining-the-karaoke-microphone-card', 'FAST Skill Declining the Karaoke Microphone Card', 'dbt'::resource_kind, 'A FAST card for declining the microphone, the toast or the game at a party without apologizing for being who you are.', 'Use it to let the client say no to the spotlight while keeping their self-respect.', array['Adults', 'Teens']::text[], 'Ten minutes before the event', 'Being handed the microphone is a socially anxious client''s nightmare, and the usual escape is an apology so long it becomes its own spotlight. FAST asks for being Fair (to themselves and the host), no Apologies for the no, Sticking to values (they get to decline), and being Truthful (no invented sore throat). The card asks for the sentence they will say, the second sentence if pushed, and what they will do instead (cheer, pick a song for someone else). Watch for the client who leaves the party to avoid the microphone; the card is for staying.', '[{"id": "f0", "type": "textarea", "label": "The moment I expect to be handed the microphone or asked to perform:"}, {"id": "f1", "type": "textarea", "label": "Fair: what I owe the host, and what I owe myself:"}, {"id": "f2", "type": "textarea", "label": "Apologies: the apology I usually make, and the sentence without it:"}, {"id": "f3", "type": "textarea", "label": "Stick to values: why I get to decline:"}, {"id": "f4", "type": "textarea", "label": "Truthful: my honest sentence, and the second one if they push:"}, {"id": "f5", "type": "textarea", "label": "What I will do instead of performing, so I stay in the room:"}]'::jsonb, array['social anxiety', 'FAST', 'interpersonal effectiveness']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('compliment-ping-pong-receive-and-return-game', 'Compliment Ping Pong Receive and Return Game', 'game'::resource_kind, 'A partner game where compliments are hit back and forth like a ball, received with a plain thank you before the return.', 'Use it to practice receiving a compliment without deflecting, in rapid rounds.', array['Groups', 'Teens']::text[], '20 minutes', 'Rules: pairs face each other. One serves a true, specific compliment. The receiver must say thank you and one more sentence that accepts it (I worked on that, I am glad you noticed) before returning a compliment of their own. A deflection (oh, it was nothing) is a dropped ball and the point restarts. Turns: three minutes per pair, then rotate so everyone receives from someone new. Debrief: what the body did when receiving, which was harder, giving or receiving, and what the thank you sentence felt like after five rounds. Ask a pair that goes shallow for one specific compliment each.', '[{"id": "f0", "type": "textarea", "label": "What my body did when a compliment came at me:"}, {"id": "f1", "type": "textarea", "label": "The deflection I kept wanting to use:"}, {"id": "f2", "type": "textarea", "label": "Which was harder, giving or receiving, and why:"}, {"id": "f3", "type": "textarea", "label": "The compliment I received that I will remember:"}, {"id": "f4", "type": "textarea", "label": "How the plain thank you felt by the fifth round compared with the first:"}]'::jsonb, array['social anxiety', 'group', 'communication']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('their-voicemail-keep-or-delete-decision-sheet', 'Their Voicemail Keep or Delete Decision Sheet', 'worksheet'::resource_kind, 'A decision sheet for the saved voicemail from someone who has died: keep it, back it up, listen or not, and when.', 'Use it to give the client a way to decide about one recording without losing it by accident.', array['Adults']::text[], '20 minutes', 'The saved voicemail is a small, loaded object: the client fears losing it to a phone upgrade and fears listening to it in equal measure. The sheet asks what the recording is, what listening does to the client now, what losing it would mean, the practical steps to back it up (so the decision is no longer forced by a dying phone), and a rule for when and where they listen, if they choose to. Watch for the client who listens on a loop late at night; the rule about when matters as much as whether.', '[{"id": "f0", "type": "textarea", "label": "The recording, and when it was left:"}, {"id": "f1", "type": "textarea", "label": "What listening to it does to me now:"}, {"id": "f2", "type": "textarea", "label": "What losing it by accident would mean:"}, {"id": "f3", "type": "textarea", "label": "The steps to back it up, and who can help me do it this week:"}, {"id": "f4", "type": "textarea", "label": "My rule for when and where I listen, if I choose to:"}, {"id": "f5", "type": "textarea", "label": "Someone I could listen with, if I ever want company for it:"}]'::jsonb, array['grief and loss', 'decisions', 'rituals']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('crying-at-work-means-i-am-unprofessional-thought-record', 'Crying at Work Means I Am Unprofessional Thought Record', 'cbt'::resource_kind, 'A thought record for the tears that arrive at work in the months after a loss and the judgment that follows them.', 'Use it to separate a grieving body''s tears from a verdict on the client''s competence.', array['Adults']::text[], '20 minutes', 'Grief does not keep office hours, and a client who cries at their desk often adds shame to the sorrow. The record takes the moment, the hot thought (I am unprofessional), the emotion and its intensity, the evidence for and against (how coworkers actually responded, what the client thinks when a colleague cries), and the thinking traps (labeling, should statements). The balanced thought is one the client can hold while stepping away for five minutes. A box for a plan for the next wave at work is included. The record is about the thought, not the schedule.', '[{"id": "f0", "type": "textarea", "label": "The moment the tears came at work, and what I did:"}, {"id": "f1", "type": "textarea", "label": "The hot thought, and the emotion with its intensity (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "Evidence that crying at work makes me unprofessional:"}, {"id": "f3", "type": "textarea", "label": "Evidence against it, including how people actually responded and what I think when a colleague cries:"}, {"id": "f4", "type": "textarea", "label": "The thinking traps I can spot:"}, {"id": "f5", "type": "textarea", "label": "A balanced thought, and my plan for the next wave at work:"}]'::jsonb, array['grief and loss', 'thought record', 'work']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('grief-as-a-river-that-changes-width-page', 'Grief as a River That Changes Width Page', 'act'::resource_kind, 'An acceptance page that pictures grief as a river that narrows and widens along its course without ever stopping.', 'Use it to let the client stop measuring progress by whether the river has dried up.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients often believe grief should shrink in a straight line and read a wide week as going backward. The page offers a river: wide at the start, narrowing through some stretches, widening again at a bend, never dry because it is fed by love that did not end. The client maps their river so far, names the bends where it widens, describes what they do when it is wide (fight the water, wade in, sit on the bank), and what the river carries that they want to keep. Watch for the client who hears the river never drying as a sentence; the width changes, and the narrow stretches are real.', '[{"id": "f0", "type": "textarea", "label": "My river so far: where it was wide, where it narrowed:"}, {"id": "f1", "type": "textarea", "label": "The bends where it widens again, by name:"}, {"id": "f2", "type": "textarea", "label": "What I do when the river is wide (fight it, wade in, sit on the bank):"}, {"id": "f3", "type": "textarea", "label": "What the river carries that I want to keep:"}, {"id": "f4", "type": "textarea", "label": "What I would say to someone whose river is wide this week:"}]'::jsonb, array['grief and loss', 'acceptance', 'metaphor']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('observe-the-grief-wave-in-the-aisle-they-loved-card', 'Observe the Grief Wave in the Aisle They Loved Card', 'dbt'::resource_kind, 'An observe-and-describe card for the grief wave in the aisle with their favorite cereal, their coffee, their brand.', 'Use it to let the client stay in the store through a wave rather than abandon the cart.', array['Adults']::text[], 'Three minutes in the aisle', 'The grocery store is full of the person: their brand, their aisle, the thing only they ate. The card asks the client to observe the wave in the body (throat, chest, eyes), describe it in plain words without the story, name the urge (leave the cart, buy the thing, cry in the car), and decide what they will do from the describing rather than the urge. A line for what they bought or did not buy is included; either is allowed. Watch for the client who avoids the store entirely; the card is a middle step that keeps the store in their life.', '[{"id": "f0", "type": "textarea", "label": "Observe: what the wave did in my body in the aisle:"}, {"id": "f1", "type": "textarea", "label": "Describe: the feeling in plain words, without the story:"}, {"id": "f2", "type": "textarea", "label": "The urge, named but not acted on yet:"}, {"id": "f3", "type": "textarea", "label": "What I decided to do from the describing:"}, {"id": "f4", "type": "textarea", "label": "What I bought or did not buy, and what the drive home was like:"}]'::jsonb, array['grief and loss', 'observe and describe', 'mindfulness']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('their-handwriting-traced-bookmark-craft', 'Their Handwriting Traced Bookmark Craft', 'kids'::resource_kind, 'A kids craft: tracing the handwriting of someone who died, a name or a note, onto a bookmark the child keeps in a favorite book.', 'Use it to give a grieving child something made from the person''s own hand to carry around.', array['Children']::text[], '30 minutes', 'The parent finds a card, a note or a signed book with the person''s handwriting, and the child traces a word or the name onto a strip of card stock, decorating around it with colors or stickers the person would have liked. The bookmark goes in the book the child is reading now, so the person turns up at bedtime without a ceremony. The parent talks while they trace, sharing one small memory and following the child''s lead on how much to say. In session, ask the child which book the bookmark lives in. A parent who gets teary while tracing can say so; missing the person out loud is allowed.', '[{"id": "f0", "type": "textarea", "label": "Draw your bookmark here, with the word or name you traced:"}, {"id": "f1", "type": "textarea", "label": "The book my bookmark lives in right now:"}, {"id": "f2", "type": "textarea", "label": "One thing I remember about the person''s handwriting or their notes:"}, {"id": "f3", "type": "textarea", "label": "Parent: the memory I shared while we traced:"}, {"id": "f4", "type": "textarea", "label": "Parent: what my child said or asked while their hands were busy:"}]'::jsonb, array['grief and loss', 'children', 'craft']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('coworker-who-takes-credit-conversation-prep-sheet', 'Coworker Who Takes Credit Conversation Prep Sheet', 'worksheet'::resource_kind, 'A prep sheet for the conversation with the coworker who presents the client''s work as their own, kept factual and forward-looking.', 'Use it to get a specific ask on paper before a resentment becomes a scene.', array['Adults']::text[], '25 minutes', 'The credit-taking coworker produces a resentment that grows quietly until it comes out sideways. The sheet asks for two specific instances with dates, what the client wants to happen going forward (named in the meeting, copied on the email), the sentence that opens the conversation without accusation, what the coworker is likely to say and the client''s reply, and who else needs to know if nothing changes. It is a conversation prep, not a case file. Watch for the client who wants to bring up every instance from three years; two recent ones carry the point.', '[{"id": "f0", "type": "textarea", "label": "Two recent, specific instances, with dates and what was said:"}, {"id": "f1", "type": "textarea", "label": "What I want to happen going forward, in concrete terms:"}, {"id": "f2", "type": "textarea", "label": "My opening sentence, factual and without accusation:"}, {"id": "f3", "type": "textarea", "label": "What they are likely to say, and my reply to each:"}, {"id": "f4", "type": "textarea", "label": "Who else needs to know if nothing changes, and when I would tell them:"}, {"id": "f5", "type": "textarea", "label": "How I will take care of myself after the conversation, whichever way it goes:"}]'::jsonb, array['relationship issues', 'work', 'assertiveness']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('they-forgot-our-anniversary-so-they-do-not-care-sheet', 'They Forgot Our Anniversary So They Do Not Care Sheet', 'cbt'::resource_kind, 'A thought sheet for the forgotten date and the leap from a missed anniversary to not being loved.', 'Use it to separate a lapse of memory from a measure of love before the fight begins.', array['Adults']::text[], '20 minutes', 'A forgotten anniversary hurts, and the hurt reaches for a verdict: they do not care. The sheet takes the event, the hot thought, the emotion and its intensity, then the evidence for and against (the other ways this person shows they care, what the client has forgotten themselves), the thinking traps (emotional reasoning, overgeneralizing), and a balanced thought the client can say out loud to the partner, hurt included. The last box is the ask: what the client wants to happen with the date next year. The hurt stays; only the verdict goes.', '[{"id": "f0", "type": "textarea", "label": "What happened, and the hot thought in my words:"}, {"id": "f1", "type": "textarea", "label": "The emotion, and its intensity (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "Evidence that forgetting means they do not care:"}, {"id": "f3", "type": "textarea", "label": "Evidence against it, including the ways they do show care and what I have forgotten myself:"}, {"id": "f4", "type": "textarea", "label": "The thinking traps I can spot:"}, {"id": "f5", "type": "textarea", "label": "What I will say to them, hurt included, and what I want to happen next year:"}]'::jsonb, array['relationship issues', 'emotional reasoning', 'communication']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('resentment-as-a-suitcase-i-keep-packing-page', 'Resentment as a Suitcase I Keep Packing Page', 'act'::resource_kind, 'A willingness page that frames old resentments as a suitcase the client keeps packing for a trip they never take.', 'Use it to help the client notice the weight they carry into each new conversation.', array['Adults', 'Teens']::text[], '20 minutes', 'Resentment accumulates as a kind of packing: each slight folded and placed, the case carried into every new conversation with the person. The page asks the client to list what is in the suitcase, how heavy it is in a number, what carrying it costs in the present (how they listen, what they expect), and what they are packing it for (the day they finally say it all). Then one item they are willing to set down this week, not forgiven, just not carried into Thursday''s dinner. Setting down is not letting them off; the page is about the carrier''s back.', '[{"id": "f0", "type": "textarea", "label": "What is in my suitcase, item by item:"}, {"id": "f1", "type": "textarea", "label": "How heavy it is (0 to 10), and how long I have been carrying it:"}, {"id": "f2", "type": "textarea", "label": "What carrying it costs me in the present:"}, {"id": "f3", "type": "textarea", "label": "The trip I have been packing it for:"}, {"id": "f4", "type": "textarea", "label": "One item I am willing to set down this week, and what I will do with the free hand:"}]'::jsonb, array['relationship issues', 'willingness', 'metaphor']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('dear-man-for-the-roommates-overnight-guests-card', 'DEAR MAN for the Roommate''s Overnight Guests Card', 'dbt'::resource_kind, 'A DEAR MAN card for the roommate whose guest has quietly become a third tenant.', 'Use it to let the client raise a shared-space issue early, with a clear ask and a fallback.', array['Adults', 'Teens']::text[], '15 minutes to prepare', 'The overnight guest problem grows because nobody names it, and by the time it is named the client is furious. The card walks through Describe (how many nights, the facts), Express (what it is like for the client), Assert (the ask: a limit, notice, a share of the bills), Reinforce (what the roommate gets), Mindful (the line to repeat), Appear confident, and Negotiate (what the client will accept). Rehearse the Assert line aloud in session. Watch for the client who leads with the guest''s flaws; the card is about the nights, not the person.', '[{"id": "f0", "type": "textarea", "label": "Describe: the facts (how many nights this month, what has changed in the apartment):"}, {"id": "f1", "type": "textarea", "label": "Express: what it is like for me, in a sentence without blame:"}, {"id": "f2", "type": "textarea", "label": "Assert: my clear ask:"}, {"id": "f3", "type": "textarea", "label": "Reinforce: what my roommate gets from agreeing:"}, {"id": "f4", "type": "textarea", "label": "Mindful: the line I repeat if we get off track:"}, {"id": "f5", "type": "textarea", "label": "Negotiate: what I will accept instead, and when we revisit it:"}]'::jsonb, array['relationship issues', 'DEAR MAN', 'boundaries']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('who-initiates-plans-imbalance-talk-sheet-for-partners', 'Who Initiates Plans Imbalance Talk Sheet for Partners', 'couples'::resource_kind, 'A couples talk sheet for the imbalance in who suggests the date, the trip or the evening, and what each partner makes of it.', 'Use it to let a couple talk about initiative without one partner feeling accused of not caring.', array['Couples']::text[], '25 minutes', 'When one partner makes every plan, they often read the other''s passivity as indifference, and the other partner reads the planning as control or hears every suggestion as a test. The sheet asks the planner what making every plan has come to mean to them and what they want, and the other partner what stops them from suggesting things and what they want. Together they set one small arrangement (the non-planner picks the next two Saturdays, the planner says nothing about the choices) and a review date. Watch for the planner who edits the other''s first plan; the sheet includes the rule for that.', '[{"id": "f0", "type": "textarea", "label": "Planning partner: what making every plan has come to mean to me, and what I want:"}, {"id": "f1", "type": "textarea", "label": "Other partner: what stops me from suggesting things, and what I want:"}, {"id": "f2", "type": "textarea", "label": "Our small arrangement for the next month:"}, {"id": "f3", "type": "textarea", "label": "The rule for the planner when the other partner''s plan is not what they would have chosen:"}, {"id": "f4", "type": "textarea", "label": "How we will know it is working, and when we will talk again:"}]'::jsonb, array['relationship issues', 'couples', 'fairness']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('medical-exam-comfort-requests-prep-sheet', 'Medical Exam Comfort Requests Prep Sheet', 'worksheet'::resource_kind, 'A prep sheet for a medical or dental appointment, listing the requests that make an exam bearable for a survivor and how to say them.', 'Use it to give the client a plan for their body in a room where someone else is in charge of it.', array['Adults']::text[], '20 minutes before the appointment', 'Medical and dental exams can be hard for a survivor, and most clinics will accommodate requests they never hear. The sheet lists the requests the client might make (a chaperone, a particular provider, being told before each touch, keeping a gown on, stopping on a word), the ones they want, how they will communicate them (a note at check-in, a sentence to the nurse, a card), what they will do if a request is refused, and a grounding move for the table. It never asks about history. Watch for the client who would rather skip the appointment; the sheet exists so they do not have to.', '[{"id": "f0", "type": "textarea", "label": "The appointment, and what tends to be hardest about exams for me:"}, {"id": "f1", "type": "textarea", "label": "The requests I want to make, from this list or my own:"}, {"id": "f2", "type": "textarea", "label": "How I will communicate them (a note at check-in, a sentence to the nurse, a card):"}, {"id": "f3", "type": "textarea", "label": "My stop word, and what I will do if a request is refused:"}, {"id": "f4", "type": "textarea", "label": "My grounding move for the table:"}, {"id": "f5", "type": "textarea", "label": "Who I will call or text afterward, and what I will do for the rest of the day:"}]'::jsonb, array['sexual abuse', 'safety', 'health']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('if-i-tell-someone-they-will-see-me-differently-check-sheet', 'If I Tell Someone They Will See Me Differently Check Sheet', 'cbt'::resource_kind, 'A gentle in-session check sheet for the fear that telling one trusted person would change how they see the client.', 'Use it to examine the predicted reaction without rushing or requiring the telling itself.', array['Adults']::text[], '25 minutes in session', 'Many survivors carry a specific prediction about what one person''s face would do if they knew, and the prediction decides their silence. The sheet names the person, the predicted reaction, how sure the client is, what this person has done when told other hard things, and what the client would think of a friend who told them the same. It ends with a question, not a plan: does the client want to tell anyone right now, and either answer is complete. Keep it in session; it asks for no detail of what happened and must not become homework to disclose. Watch your own wish for the client to tell.', '[{"id": "f0", "type": "textarea", "label": "The person I think about telling, and the reaction I predict:"}, {"id": "f1", "type": "textarea", "label": "How sure I am of that reaction (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "What this person has done when told other hard things:"}, {"id": "f3", "type": "textarea", "label": "What I would think of a friend who told me the same:"}, {"id": "f4", "type": "textarea", "label": "Does telling anyone feel right to me right now? Either answer is fine, and what I need either way:"}]'::jsonb, array['sexual abuse', 'predictions', 'support']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('shame-as-a-coat-someone-else-put-on-me-page', 'Shame as a Coat Someone Else Put on Me Page', 'act'::resource_kind, 'An acceptance page that pictures shame as a coat someone else put on the client, worn so long it feels like skin.', 'Use it to help the client notice the shame as something placed on them rather than something they are.', array['Adults']::text[], '20 minutes in session', 'Survivors often carry shame that belongs to someone else, and over years it stops feeling like a coat and starts feeling like skin. The page asks what the coat feels like (weight, heat, where it sits), who put it on (no details of events, just the fact that it was placed), what the coat says, what the client''s own skin would feel like underneath, and one place or person around whom the coat is already a little looser. It stays present-focused and stabilizing. Watch for the client who tries to rip the coat off in session; it comes off slowly, and this page is about noticing the buttons.', '[{"id": "f0", "type": "textarea", "label": "What the coat feels like: its weight, its heat, where it sits:"}, {"id": "f1", "type": "textarea", "label": "What the coat says to me:"}, {"id": "f2", "type": "textarea", "label": "Whose coat it is, in one sentence, without any detail of how it was put on:"}, {"id": "f3", "type": "textarea", "label": "What my own skin might feel like underneath, as far as I can imagine:"}, {"id": "f4", "type": "textarea", "label": "One place or person around whom the coat already sits a little looser:"}]'::jsonb, array['sexual abuse', 'acceptance', 'stabilizing']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('self-soothe-with-a-weighted-lap-pad-in-session-card', 'Self-Soothe With a Weighted Lap Pad in Session Card', 'dbt'::resource_kind, 'A self-soothe card for a weighted lap pad or heavy blanket used in session, with the client in charge of its weight and when it comes off.', 'Use it to give the client a steadying physical anchor they control during hard conversations.', array['Adults']::text[], 'Throughout a session', 'A weighted lap pad gives the body something steady while the conversation is hard, and because the client controls it, it practices choice as much as calm. The card asks the client to notice the body before the pad, decide the weight and where it sits, rate the settling at five-minute marks, and say when it comes off. It is placed by the client, never by you. It also asks what the pad reminds them of, so a bad association is caught early. Watch for the client who keeps it on because they think you want it there; the card is their permission to remove it.', '[{"id": "f0", "type": "textarea", "label": "My body before the pad: what I notice:"}, {"id": "f1", "type": "textarea", "label": "The weight I choose and where it sits (and I decide when it comes off):"}, {"id": "f2", "type": "textarea", "label": "Settling at five, ten and fifteen minutes (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "Anything the pad reminds me of, good or bad:"}, {"id": "f4", "type": "textarea", "label": "What I would want at home that does the same job:"}]'::jsonb, array['sexual abuse', 'self-soothing', 'grounding']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('body-boss-crown-craft', 'Body Boss Crown Craft', 'kids'::resource_kind, 'A kids craft: a paper crown that says the child is the boss of their own body, with the rules of a body boss written on it.', 'Use it to give a young child a playful, concrete sense of being in charge of their body.', array['Children']::text[], '25 minutes', 'The child makes and decorates a paper crown and the parent helps write the body boss rules on it: my body belongs to me, I can say no to a touch I do not like, I can tell a grown-up I trust, no secrets about touching. The child wears it while practicing saying no and stop in a big voice to a stuffed animal who asks for a hug. The parent names two trusted grown-ups with the child. Check the parent is comfortable with the words, and remember that a disclosure from a child during or after this craft brings your mandated reporting duties. The no secrets rule matters most; do not let it be skipped.', '[{"id": "f0", "type": "textarea", "label": "Decorate your crown and write the body boss rules on it:"}, {"id": "f1", "type": "textarea", "label": "My big voice words for a touch I do not want:"}, {"id": "f2", "type": "textarea", "label": "The two trusted grown-ups I can tell anything:"}, {"id": "f3", "type": "textarea", "label": "Parent: what my child practiced saying, and how it sounded:"}, {"id": "f4", "type": "textarea", "label": "Parent: a rule we will keep using at home, and when (bath, bedtime, visits):"}]'::jsonb, array['sexual abuse', 'children', 'safety']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('coping-skills-that-work-at-3-a-m-night-list-sheet', 'Coping Skills That Work at 3 a.m. Night List Sheet', 'worksheet'::resource_kind, 'A night list of coping skills that actually work at 3 a.m., when the daytime ones need a car, a friend or daylight.', 'Use it to give the client a short list made for the hour when nothing else is open.', array['Adults', 'Teens']::text[], '20 minutes, then kept by the bed', 'Most coping lists are written for daytime and fail at 3 a.m., when the friend is asleep and the walk is not safe. The sheet asks the client what 3 a.m. is like for them, which of their usual skills are unusable at that hour, and then builds five that need only a bed, a bathroom and a silent phone (a hot washcloth, a boring audiobook, a list for tomorrow, a slow breath count). The 988 line (call or text) comes first for a night with thoughts of self-harm; build that line in session, not as homework. Watch for the client whose only night skill is scrolling, and add one alternative.', '[{"id": "f0", "type": "textarea", "label": "What 3 a.m. is like for me when it is bad:"}, {"id": "f1", "type": "textarea", "label": "My usual skills that do not work at that hour, and why:"}, {"id": "f2", "type": "textarea", "label": "Five skills that need only what is in my bedroom:"}, {"id": "f3", "type": "textarea", "label": "If the night brings thoughts of hurting myself, I call or text 988 first, and then I reach:"}, {"id": "f4", "type": "textarea", "label": "Where this list lives so I can find it half asleep:"}, {"id": "f5", "type": "textarea", "label": "The night I used it, and what worked:"}]'::jsonb, array['coping skills', 'sleep', 'safety']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('if-it-did-not-work-once-it-never-will-belief-sheet', 'If It Did Not Work Once It Never Will Belief Sheet', 'cbt'::resource_kind, 'A belief sheet for the client who drops a coping skill the first time it fails to help and concludes it is useless.', 'Use it to test an all-or-nothing rule about skills before another one is thrown out.', array['Adults', 'Teens']::text[], '20 minutes', 'Coping skills are often tried once at the worst moment and judged forever. The sheet names the skill the client gave up on, the circumstances of the failure (how distressed they were, how long they tried, whether they had practiced it when calm), the belief in words, the evidence for and against (other skills that needed practice, like anything with a learning curve), and an experiment: practice the skill five times when calm and once when mildly upset, then rate it again. Watch for the client who wants a skill that works at a ten with no practice; name that as the rule under examination.', '[{"id": "f0", "type": "textarea", "label": "The skill I gave up on, and when I tried it:"}, {"id": "f1", "type": "textarea", "label": "How distressed I was when I tried it (0 to 10), how long I gave it, and whether I had practiced it calm:"}, {"id": "f2", "type": "textarea", "label": "The belief in my words, and how strongly I hold it:"}, {"id": "f3", "type": "textarea", "label": "Evidence for and against the belief, including other things that took practice:"}, {"id": "f4", "type": "textarea", "label": "The experiment: five calm practices and one mild one, logged:"}, {"id": "f5", "type": "textarea", "label": "The skill rated again, and the belief rated again:"}]'::jsonb, array['coping skills', 'all-or-nothing', 'behavioral experiment']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('coping-skill-as-a-handrail-on-the-stairs-page', 'Coping Skill as a Handrail on the Stairs Page', 'act'::resource_kind, 'A values page that frames a coping skill as a handrail: it does not climb the stairs for you, and it keeps you climbing.', 'Use it to let the client stop expecting a skill to remove the climb.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients often judge a skill a failure because the stairs were still steep. The page offers a handrail: it does not shorten the stairs, remove the climb or carry anyone; it keeps a hand steady so the climb continues. The client names a current staircase (a hard week, a hard conversation), the handrail skills they have, what their mind says a skill should do, and what they will climb this week with a hand on the rail. The debrief asks what the rail did and did not do. Watch for the client who wants an elevator; name the wish kindly and return to the rail.', '[{"id": "f0", "type": "textarea", "label": "My current staircase, in a sentence:"}, {"id": "f1", "type": "textarea", "label": "The handrail skills I have, and which ones I actually reach for:"}, {"id": "f2", "type": "textarea", "label": "What my mind says a skill should do that a handrail does not:"}, {"id": "f3", "type": "textarea", "label": "What I will climb this week with a hand on the rail:"}, {"id": "f4", "type": "textarea", "label": "What the rail did and did not do, honestly:"}]'::jsonb, array['coping skills', 'values', 'metaphor']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('self-soothe-with-the-car-heater-vents-on-the-hands-card', 'Self-Soothe With the Car Heater Vents on the Hands Card', 'dbt'::resource_kind, 'A self-soothe card for the car: hands over the heater vents, warmth on the palms, one slow minute before driving home.', 'Use it to give the client a soothing move that happens in the one private minute many days have.', array['Adults', 'Teens']::text[], 'One minute in the parked car', 'For many clients the parked car after work or after a hard visit is the day''s only private minute, and the heater is right there. The card asks the client to hold their palms over the vents, notice the warmth arriving and spreading, breathe slowly for one minute, and only then put the car in gear. The log records distress before and after and where the car was. In warm months the cold air vent does the same job. Watch for the client who uses the minute to replay the day; the hands and the warmth are the anchor, and the replay can wait.', '[{"id": "f0", "type": "textarea", "label": "Where the car was, and what the day had been like:"}, {"id": "f1", "type": "textarea", "label": "What I noticed in my palms as the warmth arrived:"}, {"id": "f2", "type": "textarea", "label": "Distress before the minute, and after (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "Where my mind went, and how I brought it back to my hands:"}, {"id": "f4", "type": "textarea", "label": "Another one-minute place in my day this could live:"}]'::jsonb, array['coping skills', 'self-soothing', 'distress tolerance']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('block-tower-pull-a-block-do-a-skill-game', 'Block Tower Pull a Block Do a Skill Game', 'game'::resource_kind, 'A group game where each wooden block pulled from a tower names a coping skill the player must do on the spot before the next turn.', 'Use it to let a group practice skills under a little pressure and a lot of laughter.', array['Groups', 'Teens']::text[], '30 minutes', 'Rules: the group writes a coping skill on each block of a stacking tower (five slow breaths, name three blue things, stretch to the ceiling, one kind sentence to the person on your left). Players pull a block in turn, do the skill, place it on top, and the tower grows wobblier. When it falls, the player who toppled it leads the group in the skill of their choice. Turns: clockwise, no skipping. Debrief: which skills were easy in front of everyone, which were hard, what the wobble did to the body, and which block each player would take home. The skill is the turn; do not let it be rushed.', '[{"id": "f0", "type": "textarea", "label": "The skills I pulled, and which was hardest to do in front of people:"}, {"id": "f1", "type": "textarea", "label": "What the wobbling tower did to my body:"}, {"id": "f2", "type": "textarea", "label": "What happened when it fell, and how the group handled it:"}, {"id": "f3", "type": "textarea", "label": "The block I would take home:"}, {"id": "f4", "type": "textarea", "label": "A skill someone else did that I want to try:"}]'::jsonb, array['coping skills', 'group', 'play']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('crossing-the-parking-lot-in-a-thunderstorm-step-plan-sheet', 'Crossing the Parking Lot in a Thunderstorm Step Plan Sheet', 'worksheet'::resource_kind, 'A step plan for the client whose fear of storms keeps them inside the store until the sky clears, from the window to the car.', 'Use it to give the client a graded path through a storm fear that costs them hours.', array['Adults', 'Teens']::text[], 'Several storms over a season', 'Storm fear is seasonal and specific: the client waits inside, checks the radar, and loses hours to a sky that will pass. The plan builds steps from the mildest (watching rain from inside a window for five minutes) through standing in a doorway, walking to a near car in light rain, and finally crossing the lot in a real storm with the steps between. Each step is logged with predicted and actual fear and how long it took to settle. Lightning safety is real, so the sheet includes a safety rule agreed with you. Watch for the client who skips to the hardest step on a brave day.', '[{"id": "f0", "type": "textarea", "label": "My current storm rule, and what it costs me in a season:"}, {"id": "f1", "type": "textarea", "label": "My steps from the window to the car, with predicted fear for each (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "The safety rule I agree on so the steps stay sensible:"}, {"id": "f3", "type": "textarea", "label": "Each step done: actual fear, how long until it settled, what my mind said:"}, {"id": "f4", "type": "textarea", "label": "What the storms actually did, compared with my predictions:"}, {"id": "f5", "type": "textarea", "label": "The next step, and the storm I will try it in:"}]'::jsonb, array['phobias', 'exposure', 'hierarchy']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('the-spider-in-the-corner-will-drop-on-me-prediction-sheet', 'The Spider in the Corner Will Drop on Me Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for the spider in the ceiling corner and the certainty that it will drop the moment the client looks away.', 'Use it to put a specific fear prediction on paper and check it against what spiders actually do.', array['Adults', 'Teens']::text[], '15 minutes, then observation', 'Spider fear runs on specific predictions: it will drop, it will run at me, it knows I am here. The sheet asks for the prediction, the confidence, what the client already knows about what house spiders actually do (stay put, retreat, mind their web), an observation task (watch the corner spider from across the room for two minutes, twice), and what happened. It is not a request to touch or remove anything. Watch for the client who gets someone else to remove the spider before the observation; that is the avoidance the sheet is about.', '[{"id": "f0", "type": "textarea", "label": "The prediction in my words, and how sure I am (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "What I already know about what house spiders usually do:"}, {"id": "f2", "type": "textarea", "label": "The observation: where I stood, for how long, what the spider did:"}, {"id": "f3", "type": "textarea", "label": "What my body did during the two minutes, and how it settled:"}, {"id": "f4", "type": "textarea", "label": "The prediction rated again:"}, {"id": "f5", "type": "textarea", "label": "What I will do the next time I see one, before calling anyone:"}]'::jsonb, array['phobias', 'predictions', 'exposure']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('willing-to-stand-near-the-edge-of-the-pool-page', 'Willing to Stand Near the Edge of the Pool Page', 'act'::resource_kind, 'A willingness page for a fear of deep water, standing at the edge of the pool with the fear present and the feet staying.', 'Use it to help the client make room for the fear while keeping the feet where they chose to put them.', array['Adults', 'Teens']::text[], 'One visit to the pool, then 15 minutes', 'Water fear keeps clients on the far side of the deck, and the family swims without them. The page asks what the client wants from the water (the kids, the summer, the exercise), what shows up in the body at the edge, what the mind says will happen, and what willingness looks like: feet at the edge, hands open, breath slow, the fear allowed to stay. The practice is five minutes at the edge, no entry required. Watch for the client who turns the five minutes into a test of courage; willingness is quiet and the feet just stay.', '[{"id": "f0", "type": "textarea", "label": "What I want from the water that the fear has been keeping me from:"}, {"id": "f1", "type": "textarea", "label": "What shows up in my body at the edge, and what my mind says will happen:"}, {"id": "f2", "type": "textarea", "label": "What willingness looks like for me at the edge: feet, hands, breath:"}, {"id": "f3", "type": "textarea", "label": "My five minutes: what happened, and what the fear did when I let it stay:"}, {"id": "f4", "type": "textarea", "label": "The next edge I am willing to stand at:"}]'::jsonb, array['phobias', 'willingness', 'values']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('cope-ahead-imagery-for-the-flu-shot-line-card', 'Cope Ahead Imagery for the Flu Shot Line Card', 'dbt'::resource_kind, 'A cope ahead card for the needle fear in the pharmacy line, rehearsed from the door to the bandage.', 'Use it to let the client walk through the whole shot in imagination with skills in place before the real line.', array['Adults', 'Teens']::text[], '15 minutes before the appointment', 'Needle fear turns a two-minute shot into a week of dread. Cope ahead asks the client to describe the scene from the pharmacy door to the bandage, name the hardest moment (the sleeve, the swab, the sight of the needle), choose the skills for each (paced breathing, looking at a fixed point, applied tension if fainting is the fear), and run the whole scene in imagination with those skills until it is boring. The card ends with the appointment time. Watch for the client who rehearses the dread rather than the skills; the imagery is of coping, not of suffering.', '[{"id": "f0", "type": "textarea", "label": "The scene from the door to the bandage, in order:"}, {"id": "f1", "type": "textarea", "label": "My hardest moment, and what my body does there:"}, {"id": "f2", "type": "textarea", "label": "The skill for each hard point (and whether I will look away or at a fixed spot):"}, {"id": "f3", "type": "textarea", "label": "The scene run with the skills in place, in a few lines:"}, {"id": "f4", "type": "textarea", "label": "The appointment time, and what I will do right after:"}]'::jsonb, array['phobias', 'cope ahead', 'health']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('brave-owl-meets-the-thunder-boom-play', 'Brave Owl Meets the Thunder Boom Play', 'kids'::resource_kind, 'A kids play tool: a stuffed owl who is scared of thunder practices brave steps during a storm with the child as the coach.', 'Use it to let a child coach a toy through a storm fear instead of being the scared one.', array['Children']::text[], '20 minutes during or before a storm', 'The child picks a stuffed owl (or any toy) who is very scared of thunder and becomes the owl''s coach. The parent plays the storm with a drum, a pot lid or a recording, starting quiet and getting louder, and the child teaches the owl brave steps: a slow breath, counting after the flash, saying the storm is outside and we are inside, holding a cozy blanket. The owl gets a brave badge after each storm. In session, ask the child what the owl is best at. Watch for the parent who skips the loud part to spare the child; the quiet-to-loud build is the whole game, and the child controls the volume.', '[{"id": "f0", "type": "textarea", "label": "Draw your brave owl and write what scares it most about storms:"}, {"id": "f1", "type": "textarea", "label": "The brave steps I taught the owl, in order:"}, {"id": "f2", "type": "textarea", "label": "How loud the storm got before the owl needed a break:"}, {"id": "f3", "type": "textarea", "label": "The owl''s brave badge for today:"}, {"id": "f4", "type": "textarea", "label": "Parent: what my child said about their own fear while coaching the owl:"}]'::jsonb, array['phobias', 'children', 'play']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('mirror-check-count-and-delay-log-sheet', 'Mirror Check Count and Delay Log Sheet', 'worksheet'::resource_kind, 'A self-monitoring log for mirror checking: how often, how long, what it was looking for, and a small delay practiced each day.', 'Use it to make a hidden habit visible and give the client one adjustable lever.', array['Adults', 'Teens']::text[], 'One week of logging', 'Mirror checking is often invisible to the client until it is counted. The log asks for each check: the mirror (bathroom, phone, shop window), how long, what the client was looking for, and how they felt leaving it. After two days of baseline, the client adds a small delay (thirty seconds, then two minutes) before each check and logs what the urge did. Nothing on the sheet rates or measures the body or asks what the client saw. Watch for the client who replaces mirrors with photos; add photos to the count.', '[{"id": "f0", "type": "textarea", "label": "Each check: the mirror, how long, what I was looking for, how I felt leaving it:"}, {"id": "f1", "type": "textarea", "label": "After two days, the delay I will add before each check:"}, {"id": "f2", "type": "textarea", "label": "What the urge did during the delay (0 to 10 at the start, at the end):"}, {"id": "f3", "type": "textarea", "label": "Checks I skipped altogether, and what I did instead:"}, {"id": "f4", "type": "textarea", "label": "What the week''s count shows:"}, {"id": "f5", "type": "textarea", "label": "The delay I will try next week:"}]'::jsonb, array['body image', 'self-monitoring', 'checking']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('everyone-noticed-my-face-broke-out-spotlight-sheet', 'Everyone Noticed My Face Broke Out Spotlight Sheet', 'cbt'::resource_kind, 'A spotlight effect sheet for the breakout, the blemish or the bad hair day the client is sure every person in the room is studying.', 'Use it to test how much attention a visible flaw actually gets from other people.', array['Adults', 'Teens']::text[], '15 minutes', 'The spotlight effect makes a blemish feel like a headline. The sheet asks what the client believes everyone noticed, how many people they think saw it, how many actually said anything, what the client themselves noticed about other people''s skin that day (usually nothing), and a small experiment: go into one room without covering it and count who comments. The balanced thought is one for the mirror in the morning. It never mentions weight, size or anything measured; the subject is attention. Watch for the client who cancels plans until it clears; that is the avoidance the sheet addresses.', '[{"id": "f0", "type": "textarea", "label": "What I am sure everyone noticed, and how many people I think saw it:"}, {"id": "f1", "type": "textarea", "label": "How many actually said anything:"}, {"id": "f2", "type": "textarea", "label": "What I noticed about other people''s faces and hair that day:"}, {"id": "f3", "type": "textarea", "label": "The experiment: one room, no covering, and who commented:"}, {"id": "f4", "type": "textarea", "label": "A balanced thought for the mirror tomorrow morning:"}, {"id": "f5", "type": "textarea", "label": "A plan I will keep this week instead of canceling:"}]'::jsonb, array['body image', 'spotlight effect', 'thinking traps']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('body-as-the-boat-not-the-cargo-page', 'Body as the Boat Not the Cargo Page', 'act'::resource_kind, 'An acceptance page that frames the body as the boat that carries the client''s life, not the cargo to be inspected.', 'Use it to shift the client''s attention from how the body looks to what it carries.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients consumed by appearance treat the body as cargo: weighed, inspected, found wanting. The page offers the boat: it carries the cargo (the people, the work, the mornings), gets scratched, and is judged by whether it floats and where it goes. The client lists what their boat has carried this month, what their mind says about the hull, what the boat would say if asked what it is for, and one voyage this week they will take in the boat as it is. It never mentions size or measurement. Watch for the client who turns boat care into another inspection; the page is about the voyage.', '[{"id": "f0", "type": "textarea", "label": "What my boat has carried this month: people, work, mornings:"}, {"id": "f1", "type": "textarea", "label": "What my mind says about the hull:"}, {"id": "f2", "type": "textarea", "label": "What the boat would say it is for, if I asked it:"}, {"id": "f3", "type": "textarea", "label": "One voyage I will take this week in the boat as it is:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the boat when I was busy with the voyage:"}]'::jsonb, array['body image', 'acceptance', 'metaphor']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('mindfulness-of-the-hot-shower-not-the-reflection-card', 'Mindfulness of the Hot Shower Not the Reflection Card', 'dbt'::resource_kind, 'A mindfulness card for the shower: attention on the water, heat and sound, with the mirror left fogged for the first minute after.', 'Use it to give the client a daily minute in the body as a sensation rather than a picture.', array['Adults', 'Teens']::text[], 'Five minutes daily', 'The bathroom is where appearance checking lives, and the shower is a chance to be in the body without looking at it. The card asks the client to observe the water on the shoulders, the heat, the sound, the smell of the soap, one-mindfully, for the length of the shower, and to leave the mirror fogged for the first minute after stepping out. The log records where the mind went and how the minute after felt. No part of it asks what the client saw or how they rate anything. Watch for the client who wipes the mirror to start the day''s inspection early; the fog is the practice.', '[{"id": "f0", "type": "textarea", "label": "What I noticed in the water, the heat, the sound and the smell:"}, {"id": "f1", "type": "textarea", "label": "Where my mind went, and how I came back to the sensations:"}, {"id": "f2", "type": "textarea", "label": "What the fogged minute after was like:"}, {"id": "f3", "type": "textarea", "label": "How the rest of the morning felt compared with a checking morning:"}, {"id": "f4", "type": "textarea", "label": "One other daily sensation I could give this attention:"}]'::jsonb, array['body image', 'mindfulness', 'self-soothing']::text[], '2026-11-26T15:00:00+00:00'::timestamptz),
  ('getting-ready-side-by-side-mirror-time-pact-for-partners', 'Getting Ready Side by Side Mirror Time Pact for Partners', 'couples'::resource_kind, 'A couples pact for the shared bathroom mirror in the morning: what gets said, what does not, and how each partner wants to be seen.', 'Use it to let a couple make the morning mirror a kinder place for both.', array['Couples']::text[], '20 minutes', 'The shared mirror is where one partner''s self-criticism is said aloud and the other''s silence or reassurance both land wrong. The pact asks each partner what they say about themselves at the mirror, what they want the other to do when they hear it (nothing, a hand, a change of subject, a specific sentence), and what comments about appearance they want kept out of the morning entirely, compliments included if that is their wish. Both write their own part. Nothing in it is about size or measurement. The pact is about what the other does when self-criticism slips out, not a promise to stop it.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I tend to say about myself at the mirror, and what I want you to do when you hear it:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I tend to say about myself at the mirror, and what I want you to do when you hear it:"}, {"id": "f2", "type": "textarea", "label": "The comments about appearance we both want kept out of the morning:"}, {"id": "f3", "type": "textarea", "label": "One thing each of us wants to hear instead, if anything:"}, {"id": "f4", "type": "textarea", "label": "How we will check in after a week:"}]'::jsonb, array['body image', 'couples', 'self-criticism']::text[], '2026-11-26T15:00:00+00:00'::timestamptz)
